INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_rit_65028893b69a', 'rituals/united_annual_festival', 'ritual', 'united_annual_festival', '聯合年祭', '由各部落輪流或共同辦理，以歌舞、競賽與交流凝聚卑南族共同體意識。', '由各部落輪流或共同辦理，以歌舞、競賽與交流凝聚卑南族共同體意識。；時間提示：時間不定；由部落聯合會議或主辦單位公告；類別：跨部落交流', '["卑南族", "祭儀", "聯合年祭", "跨部落交流", "時間不定；由部落聯合會議或主辦單位公告", "聯合年祭", "十社", "歌舞", "交流", "族群凝聚"]', '["cip_puyuma_profile"]', 'public', 'verified_source_public_summary', 'low', 100, '[{"heading": "公開摘要", "body_zh": "由各部落輪流或共同辦理，以歌舞、競賽與交流凝聚卑南族共同體意識。"}, {"heading": "時間提示", "body_zh": "時間不定；由部落聯合會議或主辦單位公告"}, {"heading": "公開使用限制", "body_zh": "僅可作公開摘要與導覽，不產生祭儀流程、禁忌細節或仿作教學。"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_fact_73b875ce3d7d', 'facts/profile_plain_crossroads', 'fact', 'profile_plain_crossroads', '族群簡介', '卑南族位於多族群交會的平原地帶，長期與外界文化接觸，同時仍維繫傳統文化與生活。', '卑南族位於多族群交會的平原地帶，長期與外界文化接觸，同時仍維繫傳統文化與生活。', '["卑南族", "族群簡介"]', '["cip_puyuma_profile"]', 'public', 'verified_public', 'low', 200, '[{"heading": "知識摘要", "body_zh": "卑南族位於多族群交會的平原地帶，長期與外界文化接觸，同時仍維繫傳統文化與生活。"}, {"heading": "來源提示", "body_zh": "CIP 卑南族頁：族群簡介"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_fact_df9c455bd6d8', 'facts/profile_age_house_core', 'fact', 'profile_age_house_core', '社會制度', '卑南族社會以嚴謹的年齡階級組織與會所制度聞名，這兩者是理解部落公共生活的重要基礎。', '卑南族社會以嚴謹的年齡階級組織與會所制度聞名，這兩者是理解部落公共生活的重要基礎。', '["卑南族", "社會制度"]', '["cip_puyuma_profile"]', 'preview', 'verified_public', 'medium', 201, '[{"heading": "知識摘要", "body_zh": "卑南族社會以嚴謹的年齡階級組織與會所制度聞名，這兩者是理解部落公共生活的重要基礎。"}, {"heading": "來源提示", "body_zh": ""}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_fact_3a0d45171101', 'facts/profile_annual_rituals_overview', 'fact', 'profile_annual_rituals_overview', '祭儀', '卑南族現今仍有小米除草完工、小米收穫、少年年祭、年祭與大獵祭等年度慶典，其中年祭規模最大。', '卑南族現今仍有小米除草完工、小米收穫、少年年祭、年祭與大獵祭等年度慶典，其中年祭規模最大。', '["卑南族", "祭儀"]', '["cip_puyuma_profile"]', 'preview', 'verified_public', 'medium', 202, '[{"heading": "知識摘要", "body_zh": "卑南族現今仍有小米除草完工、小米收穫、少年年祭、年祭與大獵祭等年度慶典，其中年祭規模最大。"}, {"heading": "來源提示", "body_zh": ""}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_fact_a7f146ae7199', 'facts/name_puyuma_pinuyumayan_distinction', 'fact', 'name_puyuma_pinuyumayan_distinction', '正名', 'Puyuma 源自南王部落名稱；為避免族稱與部落名混用，近年有族人提倡以 Pinuyumayan 作為卑南族族稱。', 'Puyuma 源自南王部落名稱；為避免族稱與部落名混用，近年有族人提倡以 Pinuyumayan 作為卑南族族稱。', '["卑南族", "正名"]', '["cip_puyuma_profile"]', 'public', 'verified_public', 'low', 203, '[{"heading": "知識摘要", "body_zh": "Puyuma 源自南王部落名稱；為避免族稱與部落名混用，近年有族人提倡以 Pinuyumayan 作為卑南族族稱。"}, {"heading": "來源提示", "body_zh": ""}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_fact_34f5e1b5780f', 'facts/origin_bamboo_stone', 'fact', 'origin_bamboo_stone', '起源敘事', '卑南族起源敘事常見「竹生」與「石生」兩大說法，前者以卑南社/南王為中心，後者以知本社為中心。', '卑南族起源敘事常見「竹生」與「石生」兩大說法，前者以卑南社/南王為中心，後者以知本社為中心。', '["卑南族", "起源敘事"]', '["cip_puyuma_profile"]', 'preview', 'verified_public', 'medium', 204, '[{"heading": "知識摘要", "body_zh": "卑南族起源敘事常見「竹生」與「石生」兩大說法，前者以卑南社/南王為中心，後者以知本社為中心。"}, {"heading": "來源提示", "body_zh": ""}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_fact_8e7bdabcd5f4', 'facts/settlement_core_area', 'fact', 'settlement_core_area', '部落地理', '現代卑南族主要以臺東平原的臺東市、卑南鄉一帶為核心，也有族人居住成功鎮、太麻里鄉或移居都市。', '現代卑南族主要以臺東平原的臺東市、卑南鄉一帶為核心，也有族人居住成功鎮、太麻里鄉或移居都市。', '["卑南族", "部落地理"]', '["cip_puyuma_profile"]', 'public', 'verified_public', 'low', 205, '[{"heading": "知識摘要", "body_zh": "現代卑南族主要以臺東平原的臺東市、卑南鄉一帶為核心，也有族人居住成功鎮、太麻里鄉或移居都市。"}, {"heading": "來源提示", "body_zh": ""}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_fact_18a4f77875ba', 'facts/community_list_public', 'fact', 'community_list_public', '部落地理', '公開資料列出知本、建和、南王、寶桑、利嘉、泰安、上賓朗、下賓朗、初鹿、龍過脈等卑南族主要部落脈絡。', '公開資料列出知本、建和、南王、寶桑、利嘉、泰安、上賓朗、下賓朗、初鹿、龍過脈等卑南族主要部落脈絡。', '["卑南族", "部落地理"]', '["cip_puyuma_profile"]', 'public', 'verified_public', 'low', 206, '[{"heading": "知識摘要", "body_zh": "公開資料列出知本、建和、南王、寶桑、利嘉、泰安、上賓朗、下賓朗、初鹿、龍過脈等卑南族主要部落脈絡。"}, {"heading": "來源提示", "body_zh": ""}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_fact_56b49cc9b9f3', 'facts/agriculture_millet_to_rice', 'fact', 'agriculture_millet_to_rice', '產業', '卑南族早期農作以小米為重要作物，後來也有禾、麻、菽、麥等作物；水稻耕作技術在歷史敘事中與卑南王 Pinadray 有關。', '卑南族早期農作以小米為重要作物，後來也有禾、麻、菽、麥等作物；水稻耕作技術在歷史敘事中與卑南王 Pinadray 有關。', '["卑南族", "產業"]', '["cip_puyuma_profile"]', 'public', 'verified_public', 'low', 207, '[{"heading": "知識摘要", "body_zh": "卑南族早期農作以小米為重要作物，後來也有禾、麻、菽、麥等作物；水稻耕作技術在歷史敘事中與卑南王 Pinadray 有關。"}, {"heading": "來源提示", "body_zh": ""}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_fact_a35f027ba0a0', 'facts/modern_economic_crops', 'fact', 'modern_economic_crops', '產業', '1960年代以後，部分卑南族地區的作物轉向釋迦、荖葉等經濟作物。', '1960年代以後，部分卑南族地區的作物轉向釋迦、荖葉等經濟作物。', '["卑南族", "產業"]', '["cip_puyuma_profile"]', 'public', 'verified_public', 'low', 208, '[{"heading": "知識摘要", "body_zh": "1960年代以後，部分卑南族地區的作物轉向釋迦、荖葉等經濟作物。"}, {"heading": "來源提示", "body_zh": ""}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_fact_556ef9d4d095', 'facts/traditional_food_staples', 'fact', 'traditional_food_staples', '飲食', '卑南族傳統飲食包含粟、旱稻、甘薯、芋頭，以及狩獵、河川魚貝取得的蛋白質來源。', '卑南族傳統飲食包含粟、旱稻、甘薯、芋頭，以及狩獵、河川魚貝取得的蛋白質來源。', '["卑南族", "飲食"]', '["cip_puyuma_profile"]', 'public', 'verified_public', 'low', 209, '[{"heading": "知識摘要", "body_zh": "卑南族傳統飲食包含粟、旱稻、甘薯、芋頭，以及狩獵、河川魚貝取得的蛋白質來源。"}, {"heading": "來源提示", "body_zh": ""}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_fact_77aec702c3c2', 'facts/festival_food_shell_ginger', 'fact', 'festival_food_shell_ginger', '飲食', '月桃葉包裹的糯米粉糰、鹹豬肉做成的月桃小米或糯米粿粽，是公開介紹中常見的卑南族慶典食物代表。', '月桃葉包裹的糯米粉糰、鹹豬肉做成的月桃小米或糯米粿粽，是公開介紹中常見的卑南族慶典食物代表。', '["卑南族", "飲食"]', '["cip_puyuma_profile"]', 'public', 'verified_public', 'low', 210, '[{"heading": "知識摘要", "body_zh": "月桃葉包裹的糯米粉糰、鹹豬肉做成的月桃小米或糯米粿粽，是公開介紹中常見的卑南族慶典食物代表。"}, {"heading": "來源提示", "body_zh": ""}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_fact_78af107634d6', 'facts/betel_nut_role', 'fact', 'betel_nut_role', '飲食/祭祀', '檳榔在卑南族生活與祭祀中具有重要性，既是日常生活中的食用物，也可作為祭祀物品。', '檳榔在卑南族生活與祭祀中具有重要性，既是日常生活中的食用物，也可作為祭祀物品。', '["卑南族", "飲食/祭祀"]', '["cip_puyuma_profile"]', 'preview', 'verified_public', 'medium', 211, '[{"heading": "知識摘要", "body_zh": "檳榔在卑南族生活與祭祀中具有重要性，既是日常生活中的食用物，也可作為祭祀物品。"}, {"heading": "來源提示", "body_zh": ""}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_fact_c92d28c08312', 'facts/clothing_colors_patterns', 'fact', 'clothing_colors_patterns', '服飾', '卑南族傳統服飾以麻為材料，常見紅、黃、綠並搭配黑白色，呈現多層次菱形紋路與十字繡花形紋。', '卑南族傳統服飾以麻為材料，常見紅、黃、綠並搭配黑白色，呈現多層次菱形紋路與十字繡花形紋。', '["卑南族", "服飾"]', '["cip_puyuma_profile"]', 'public', 'verified_public', 'low', 212, '[{"heading": "知識摘要", "body_zh": "卑南族傳統服飾以麻為材料，常見紅、黃、綠並搭配黑白色，呈現多層次菱形紋路與十字繡花形紋。"}, {"heading": "來源提示", "body_zh": ""}]');
