INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_fact_a4c03c939956', 'facts/language_regional_variation', 'fact', 'language_regional_variation', '族語', '卑南語因部落區位與族群接觸經驗而有差異，例如知本受排灣族、魯凱族語影響，北部卑南部落受阿美族語發音方式影響。', '卑南語因部落區位與族群接觸經驗而有差異，例如知本受排灣族、魯凱族語影響，北部卑南部落受阿美族語發音方式影響。', '["卑南族", "族語"]', '["cip_puyuma_profile"]', 'public', 'verified_public', 'low', 228, '[{"heading": "知識摘要", "body_zh": "卑南語因部落區位與族群接觸經驗而有差異，例如知本受排灣族、魯凱族語影響，北部卑南部落受阿美族語發音方式影響。"}, {"heading": "來源提示", "body_zh": ""}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_fact_f70ff0031691', 'facts/kinship_matrilineal_summary', 'fact', 'kinship_matrilineal_summary', '親屬制度', '卑南族傳統婚姻家庭以母系大家族制為原則，重視母系家系、本家與宗家觀念；現代運作已有變化。', '卑南族傳統婚姻家庭以母系大家族制為原則，重視母系家系、本家與宗家觀念；現代運作已有變化。', '["卑南族", "親屬制度"]', '["cip_puyuma_profile"]', 'preview', 'verified_public', 'high', 229, '[{"heading": "知識摘要", "body_zh": "卑南族傳統婚姻家庭以母系大家族制為原則，重視母系家系、本家與宗家觀念；現代運作已有變化。"}, {"heading": "來源提示", "body_zh": ""}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_fact_0f30640f38a0', 'facts/kinship_inheritance_marriage', 'fact', 'kinship_inheritance_marriage', '親屬制度', '公開介紹指出傳統上家族氏名與家屋財產由長女繼承，居住方式以男子入居女方家庭為原則，但現代從妻居已相當少見。', '公開介紹指出傳統上家族氏名與家屋財產由長女繼承，居住方式以男子入居女方家庭為原則，但現代從妻居已相當少見。', '["卑南族", "親屬制度"]', '["cip_puyuma_profile"]', 'preview', 'verified_public', 'high', 230, '[{"heading": "知識摘要", "body_zh": "公開介紹指出傳統上家族氏名與家屋財產由長女繼承，居住方式以男子入居女方家庭為原則，但現代從妻居已相當少見。"}, {"heading": "來源提示", "body_zh": ""}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_fact_c069932583a1', 'facts/leadership_ayawan_rahan', 'fact', 'leadership_ayawan_rahan', '部落制度', '卑南族傳統部落政治領袖 ayawan 負責重大事件協調；祭司 rahan 掌管祭祀禮儀並需熟知曆法、氣象、歷史、歌謠與舞蹈。', '卑南族傳統部落政治領袖 ayawan 負責重大事件協調；祭司 rahan 掌管祭祀禮儀並需熟知曆法、氣象、歷史、歌謠與舞蹈。', '["卑南族", "部落制度"]', '["cip_puyuma_profile"]', 'preview', 'verified_public', 'high', 231, '[{"heading": "知識摘要", "body_zh": "卑南族傳統部落政治領袖 ayawan 負責重大事件協調；祭司 rahan 掌管祭祀禮儀並需熟知曆法、氣象、歷史、歌謠與舞蹈。"}, {"heading": "來源提示", "body_zh": ""}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_fact_655ae359faf1', 'facts/shaman_role_public_summary', 'fact', 'shaman_role_public_summary', '信仰/巫師', '公開介紹指出巫師 na temaramaw 可為男女，與祈福、治病、驅邪等照護需求相關；平台僅可公開摘要，不得產生作法教學。', '公開介紹指出巫師 na temaramaw 可為男女，與祈福、治病、驅邪等照護需求相關；平台僅可公開摘要，不得產生作法教學。', '["卑南族", "信仰/巫師"]', '["cip_puyuma_profile"]', 'preview', 'verified_public', 'high', 232, '[{"heading": "知識摘要", "body_zh": "公開介紹指出巫師 na temaramaw 可為男女，與祈福、治病、驅邪等照護需求相關；平台僅可公開摘要，不得產生作法教學。"}, {"heading": "來源提示", "body_zh": ""}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_fact_b0e1dc880350', 'facts/age_grade_training_stages', 'fact', 'age_grade_training_stages', '年齡階級', '公開介紹指出少年約12、13歲進入少年會所，17、18歲轉入成年會所；訓練包含體能、知識、競走、摔角、野外求生與狩獵等。', '公開介紹指出少年約12、13歲進入少年會所，17、18歲轉入成年會所；訓練包含體能、知識、競走、摔角、野外求生與狩獵等。', '["卑南族", "年齡階級"]', '["cip_puyuma_profile"]', 'preview', 'verified_public', 'medium', 233, '[{"heading": "知識摘要", "body_zh": "公開介紹指出少年約12、13歲進入少年會所，17、18歲轉入成年會所；訓練包含體能、知識、競走、摔角、野外求生與狩獵等。"}, {"heading": "來源提示", "body_zh": ""}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_fact_88774608570b', 'facts/revitalization_1991', 'fact', 'revitalization_1991', '文化復振', '公開介紹指出1991年前後，知本、初鹿與南王等部落建新會所、成立青年會或文化工作協會，推動尋根與母語復振。', '公開介紹指出1991年前後，知本、初鹿與南王等部落建新會所、成立青年會或文化工作協會，推動尋根與母語復振。', '["卑南族", "文化復振"]', '["cip_puyuma_profile"]', 'public', 'verified_public', 'low', 234, '[{"heading": "知識摘要", "body_zh": "公開介紹指出1991年前後，知本、初鹿與南王等部落建新會所、成立青年會或文化工作協會，推動尋根與母語復振。"}, {"heading": "來源提示", "body_zh": ""}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_fact_5c4e3800f6b4', 'facts/spiritual_biruwa', 'fact', 'spiritual_biruwa', '傳統信仰', '卑南族傳統信仰認為自然、天地、四方、祖先與死者之靈等皆存在，神靈稱為 biruwa。', '卑南族傳統信仰認為自然、天地、四方、祖先與死者之靈等皆存在，神靈稱為 biruwa。', '["卑南族", "傳統信仰"]', '["cip_puyuma_profile"]', 'preview', 'verified_public', 'high', 235, '[{"heading": "知識摘要", "body_zh": "卑南族傳統信仰認為自然、天地、四方、祖先與死者之靈等皆存在，神靈稱為 biruwa。"}, {"heading": "來源提示", "body_zh": ""}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_fact_32b0c5ff8673', 'facts/divination_public_summary', 'fact', 'divination_public_summary', '傳統信仰', '公開介紹提到卑南族巫術中有占卜行為，並以夢兆與鳥占為主；此內容僅適合摘要，不可操作化。', '公開介紹提到卑南族巫術中有占卜行為，並以夢兆與鳥占為主；此內容僅適合摘要，不可操作化。', '["卑南族", "傳統信仰"]', '["cip_puyuma_profile"]', 'preview', 'verified_public', 'high', 236, '[{"heading": "知識摘要", "body_zh": "公開介紹提到卑南族巫術中有占卜行為，並以夢兆與鳥占為主；此內容僅適合摘要，不可操作化。"}, {"heading": "來源提示", "body_zh": ""}]');
