INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_fact_359c75667228', 'facts/ritual_calendar_public', 'fact', 'ritual_calendar_public', '祭儀時間軸', '公開介紹列出3月婦女除草完工慶、4月祖先登陸與發祥地祭祖、7月小米收穫祭、12月年祭等年度脈絡；實際日期仍需依部落公告。', '公開介紹列出3月婦女除草完工慶、4月祖先登陸與發祥地祭祖、7月小米收穫祭、12月年祭等年度脈絡；實際日期仍需依部落公告。', '["卑南族", "祭儀時間軸"]', '["cip_puyuma_profile"]', 'preview', 'verified_public', 'medium', 238, '[{"heading": "知識摘要", "body_zh": "公開介紹列出3月婦女除草完工慶、4月祖先登陸與發祥地祭祖、7月小米收穫祭、12月年祭等年度脈絡；實際日期仍需依部落公告。"}, {"heading": "來源提示", "body_zh": ""}]');
