INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_fact_38821d96e2b2', 'facts/ancestral_landing_rite_public', 'fact', 'ancestral_landing_rite_public', '祭儀', '知本、建和部落每年4月會由祭司與女巫師帶領族人至祖先登陸地祭祀歷代祖先，具有慎終追遠意義。', '知本、建和部落每年4月會由祭司與女巫師帶領族人至祖先登陸地祭祀歷代祖先，具有慎終追遠意義。', '["卑南族", "祭儀"]', '["cip_puyuma_profile"]', 'preview', 'verified_public', 'high', 240, '[{"heading": "知識摘要", "body_zh": "知本、建和部落每年4月會由祭司與女巫師帶領族人至祖先登陸地祭祀歷代祖先，具有慎終追遠意義。"}, {"heading": "來源提示", "body_zh": ""}]');
