INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_fact_6aa2ad3ffd92', 'facts/swing_millet_symbolism', 'fact', 'swing_millet_symbolism', '祭儀/活動', '部分部落在小米收穫祭期間於會所廣場搭設鞦韆架，公開介紹指出盪得越高象徵祈願隔年小米長得更高更多。', '部分部落在小米收穫祭期間於會所廣場搭設鞦韆架，公開介紹指出盪得越高象徵祈願隔年小米長得更高更多。', '["卑南族", "祭儀/活動"]', '["cip_puyuma_profile"]', 'preview', 'verified_public', 'medium', 242, '[{"heading": "知識摘要", "body_zh": "部分部落在小米收穫祭期間於會所廣場搭設鞦韆架，公開介紹指出盪得越高象徵祈願隔年小米長得更高更多。"}, {"heading": "來源提示", "body_zh": ""}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_fact_ab8753714dc8', 'facts/annual_festival_three_weeks', 'fact', 'annual_festival_three_weeks', '年祭', '年祭是舊年尾、新年頭之間的活動，公開介紹指出其包含猴祭、大獵祭等活動，前後可接近三週。', '年祭是舊年尾、新年頭之間的活動，公開介紹指出其包含猴祭、大獵祭等活動，前後可接近三週。', '["卑南族", "年祭"]', '["cip_puyuma_profile"]', 'preview', 'verified_public', 'medium', 243, '[{"heading": "知識摘要", "body_zh": "年祭是舊年尾、新年頭之間的活動，公開介紹指出其包含猴祭、大獵祭等活動，前後可接近三週。"}, {"heading": "來源提示", "body_zh": ""}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_fact_61aea49eeaee', 'facts/monkey_rite_symbolic_modern', 'fact', 'monkey_rite_symbolic_modern', '少年年祭/猴祭', '猴祭傳統上與少年膽識訓練有關；現代公開活動已改以草猴等象徵物代替真猴。', '猴祭傳統上與少年膽識訓練有關；現代公開活動已改以草猴等象徵物代替真猴。', '["卑南族", "少年年祭/猴祭"]', '["cip_puyuma_profile"]', 'preview', 'verified_public', 'high', 244, '[{"heading": "知識摘要", "body_zh": "猴祭傳統上與少年膽識訓練有關；現代公開活動已改以草猴等象徵物代替真猴。"}, {"heading": "來源提示", "body_zh": ""}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_fact_b9b21f2bfa94', 'facts/hunting_rite_modern', 'fact', 'hunting_rite_modern', '大獵祭', '大獵祭與男性成年儀式、野外求生與狩獵技能傳承相關；現代已改為定點活動，公開介紹以12月27日至31日脈絡說明。', '大獵祭與男性成年儀式、野外求生與狩獵技能傳承相關；現代已改為定點活動，公開介紹以12月27日至31日脈絡說明。', '["卑南族", "大獵祭"]', '["cip_puyuma_profile"]', 'preview', 'verified_public', 'high', 245, '[{"heading": "知識摘要", "body_zh": "大獵祭與男性成年儀式、野外求生與狩獵技能傳承相關；現代已改為定點活動，公開介紹以12月27日至31日脈絡說明。"}, {"heading": "來源提示", "body_zh": ""}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_fact_6868c9e95f72', 'facts/joint_annual_festival_1982', 'fact', 'joint_annual_festival_1982', '聯合年祭', '公開介紹指出卑南族各部落自1982年起逐漸發展出聯合年祭，由部落輪流舉辦，成為部落交誼與凝聚民族意識的重要活動。', '公開介紹指出卑南族各部落自1982年起逐漸發展出聯合年祭，由部落輪流舉辦，成為部落交誼與凝聚民族意識的重要活動。', '["卑南族", "聯合年祭"]', '["cip_puyuma_profile"]', 'preview', 'verified_public', 'medium', 246, '[{"heading": "知識摘要", "body_zh": "公開介紹指出卑南族各部落自1982年起逐漸發展出聯合年祭，由部落輪流舉辦，成為部落交誼與凝聚民族意識的重要活動。"}, {"heading": "來源提示", "body_zh": ""}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_fact_9cfd7a076f2c', 'facts/formosanbank_epark_structure', 'fact', 'formosanbank_epark_structure', '族語語料', 'FormosanBank 的 ePark 資料包含 ePark_1、ePark_2、ePark_3 等來源資料，並整理為 FormosanBank XML 格式，可作族語教材與音檔索引依據。', 'FormosanBank 的 ePark 資料包含 ePark_1、ePark_2、ePark_3 等來源資料，並整理為 FormosanBank XML 格式，可作族語教材與音檔索引依據。', '["卑南族", "族語語料"]', '["formosanbank_epark_readme"]', 'public', 'verified_public', 'low', 247, '[{"heading": "知識摘要", "body_zh": "FormosanBank 的 ePark 資料包含 ePark_1、ePark_2、ePark_3 等來源資料，並整理為 FormosanBank XML 格式，可作族語教材與音檔索引依據。"}, {"heading": "來源提示", "body_zh": ""}]');
