INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_fact_22324bba231c', 'facts/history_japanese_classification_pinuyumayan', 'fact', 'history_japanese_classification_pinuyumayan', '歷史分類', '公開資料指出，十九世紀末進入日本殖民統治時期後，卑南族在民族文化分類上被稱為 Pinuyumayan，並因主要有八個部落而被稱為「八社蕃」；平台只能將「八社」作歷史用語，不可作正式分類。', '公開資料指出，十九世紀末進入日本殖民統治時期後，卑南族在民族文化分類上被稱為 Pinuyumayan，並因主要有八個部落而被稱為「八社蕃」；平台只能將「八社」作歷史用語，不可作正式分類。', '["卑南族", "歷史分類"]', '["cip_puyuma_profile"]', 'preview', 'verified_public', 'medium', 249, '[{"heading": "知識摘要", "body_zh": "公開資料指出，十九世紀末進入日本殖民統治時期後，卑南族在民族文化分類上被稱為 Pinuyumayan，並因主要有八個部落而被稱為「八社蕃」；平台只能將「八社」作歷史用語，不可作正式分類。"}, {"heading": "來源提示", "body_zh": "CIP 卑南族頁：美麗的家園，日治時期分類與八社蕃歷史用語"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_fact_b90054abd60d', 'facts/migration_hengchun_sukaro_public', 'fact', 'migration_hengchun_sukaro_public', '歷史遷徙', '公開資料指出，十八世紀有一部分卑南族氏族遷居恆春半島並發展出稱為「斯卡羅」（sukaro）的歷史脈絡；此主題涉及跨族群歷史，平台應以來源摘要呈現並標記待專題審核。', '公開資料指出，十八世紀有一部分卑南族氏族遷居恆春半島並發展出稱為「斯卡羅」（sukaro）的歷史脈絡；此主題涉及跨族群歷史，平台應以來源摘要呈現並標記待專題審核。', '["卑南族", "歷史遷徙"]', '["cip_puyuma_profile"]', 'preview', 'verified_public', 'medium', 250, '[{"heading": "知識摘要", "body_zh": "公開資料指出，十八世紀有一部分卑南族氏族遷居恆春半島並發展出稱為「斯卡羅」（sukaro）的歷史脈絡；此主題涉及跨族群歷史，平台應以來源摘要呈現並標記待專題審核。"}, {"heading": "來源提示", "body_zh": "CIP 卑南族頁：美麗的家園，恆春半島與斯卡羅段落"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_fact_c42376b6b0b7', 'facts/urban_migration_modern_fields', 'fact', 'urban_migration_modern_fields', '現代發展', '公開資料指出，目前有不少卑南族人離開東部到都市發展，並活躍於各領域；平台可建立「都會族人與現代發展」內容分類，但人物條目需另行來源查證。', '公開資料指出，目前有不少卑南族人離開東部到都市發展，並活躍於各領域；平台可建立「都會族人與現代發展」內容分類，但人物條目需另行來源查證。', '["卑南族", "現代發展"]', '["cip_puyuma_profile"]', 'public', 'verified_public', 'low', 251, '[{"heading": "知識摘要", "body_zh": "公開資料指出，目前有不少卑南族人離開東部到都市發展，並活躍於各領域；平台可建立「都會族人與現代發展」內容分類，但人物條目需另行來源查證。"}, {"heading": "來源提示", "body_zh": "CIP 卑南族頁：美麗的家園，都市發展段落"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_fact_dc55f7edb123', 'facts/rice_technology_pinadray_public', 'fact', 'rice_technology_pinadray_public', '產業/歷史', '公開資料將十八世紀水稻耕作技術與器物的引進，連結到卑南王 Pinadray 的歷史敘事；此類歷史人物敘事應標示來源並避免過度擴寫。', '公開資料將十八世紀水稻耕作技術與器物的引進，連結到卑南王 Pinadray 的歷史敘事；此類歷史人物敘事應標示來源並避免過度擴寫。', '["卑南族", "產業/歷史"]', '["cip_puyuma_profile"]', 'preview', 'verified_public', 'medium', 252, '[{"heading": "知識摘要", "body_zh": "公開資料將十八世紀水稻耕作技術與器物的引進，連結到卑南王 Pinadray 的歷史敘事；此類歷史人物敘事應標示來源並避免過度擴寫。"}, {"heading": "來源提示", "body_zh": "CIP 卑南族頁：生活圖像—產業"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_fact_00a770f08464', 'facts/male_clothing_parts_public', 'fact', 'male_clothing_parts_public', '服飾', '公開資料列出男子盛裝可包含上衣、黑短褲、套褲、檳榔袋、腰袋等，盛裝時也可佩刀並配戴琉璃珠或銀飾；平台應以服飾知識卡呈現，不替代部落穿著規範。', '公開資料列出男子盛裝可包含上衣、黑短褲、套褲、檳榔袋、腰袋等，盛裝時也可佩刀並配戴琉璃珠或銀飾；平台應以服飾知識卡呈現，不替代部落穿著規範。', '["卑南族", "服飾"]', '["cip_puyuma_profile"]', 'public', 'verified_public', 'low', 253, '[{"heading": "知識摘要", "body_zh": "公開資料列出男子盛裝可包含上衣、黑短褲、套褲、檳榔袋、腰袋等，盛裝時也可佩刀並配戴琉璃珠或銀飾；平台應以服飾知識卡呈現，不替代部落穿著規範。"}, {"heading": "來源提示", "body_zh": "CIP 卑南族頁：生活圖像—服飾"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_fact_0524bcec6f3b', 'facts/young_women_clothing_public', 'fact', 'young_women_clothing_public', '服飾', '公開資料提到適婚年齡少女服飾包括頭巾、上衣、肚兜、腰裙、綁腿等；平台可作為服飾元素資料，但不自行判斷個人身分。', '公開資料提到適婚年齡少女服飾包括頭巾、上衣、肚兜、腰裙、綁腿等；平台可作為服飾元素資料，但不自行判斷個人身分。', '["卑南族", "服飾"]', '["cip_puyuma_profile"]', 'public', 'verified_public', 'low', 254, '[{"heading": "知識摘要", "body_zh": "公開資料提到適婚年齡少女服飾包括頭巾、上衣、肚兜、腰裙、綁腿等；平台可作為服飾元素資料，但不自行判斷個人身分。"}, {"heading": "來源提示", "body_zh": "CIP 卑南族頁：生活圖像—服飾"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_fact_d02c06d8208a', 'facts/leader_priest_shaman_clothing_public', 'fact', 'leader_priest_shaman_clothing_public', '服飾/身分', '公開資料指出傳統領袖與祭師盛裝另有羽冠與肩袋，女靈媒或巫師另有肩飾；平台可作摘要，但不得產生身分判定或儀式穿著教學。', '公開資料指出傳統領袖與祭師盛裝另有羽冠與肩袋，女靈媒或巫師另有肩飾；平台可作摘要，但不得產生身分判定或儀式穿著教學。', '["卑南族", "服飾/身分"]', '["cip_puyuma_profile"]', 'preview', 'verified_public', 'medium', 255, '[{"heading": "知識摘要", "body_zh": "公開資料指出傳統領袖與祭師盛裝另有羽冠與肩袋，女靈媒或巫師另有肩飾；平台可作摘要，但不得產生身分判定或儀式穿著教學。"}, {"heading": "來源提示", "body_zh": "CIP 卑南族頁：生活圖像—服飾"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_fact_cfd0f1639d0f', 'facts/architecture_private_granary_public', 'fact', 'architecture_private_granary_public', '建築', '公開資料將住家、穀倉或女巫師專用祖靈屋列入私有建築類；涉及女巫師祖靈屋配置與神聖方位時，平台僅可保留摘要並需社群審核。', '公開資料將住家、穀倉或女巫師專用祖靈屋列入私有建築類；涉及女巫師祖靈屋配置與神聖方位時，平台僅可保留摘要並需社群審核。', '["卑南族", "建築"]', '["cip_puyuma_profile"]', 'preview', 'verified_public', 'high', 256, '[{"heading": "知識摘要", "body_zh": "公開資料將住家、穀倉或女巫師專用祖靈屋列入私有建築類；涉及女巫師祖靈屋配置與神聖方位時，平台僅可保留摘要並需社群審核。"}, {"heading": "來源提示", "body_zh": "CIP 卑南族頁：生活圖像—建築"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_fact_a2ae70868675', 'facts/house_status_scale_public', 'fact', 'house_status_scale_public', '建築/社會身分', '公開資料提到傳統家屋規模大小與屋主社會地位相關，部落領導人直系家族家屋較大，旁系血親與一般家屋較小；平台應避免將此用於現代個人身分判斷。', '公開資料提到傳統家屋規模大小與屋主社會地位相關，部落領導人直系家族家屋較大，旁系血親與一般家屋較小；平台應避免將此用於現代個人身分判斷。', '["卑南族", "建築/社會身分"]', '["cip_puyuma_profile"]', 'preview', 'verified_public', 'medium', 257, '[{"heading": "知識摘要", "body_zh": "公開資料提到傳統家屋規模大小與屋主社會地位相關，部落領導人直系家族家屋較大，旁系血親與一般家屋較小；平台應避免將此用於現代個人身分判斷。"}, {"heading": "來源提示", "body_zh": "CIP 卑南族頁：生活圖像—建築—住屋"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_fact_2f5ec0e0bd4c', 'facts/musical_categories_detail_public', 'fact', 'musical_categories_detail_public', '音樂歌謠', '公開資料將卑南族歌謠分為祭儀歌謠、休閒工作歌謠與社會時代歌謠，並舉例猴祭、大獵祭、年祭歌謠以及婦女工作團工作歌等。', '公開資料將卑南族歌謠分為祭儀歌謠、休閒工作歌謠與社會時代歌謠，並舉例猴祭、大獵祭、年祭歌謠以及婦女工作團工作歌等。', '["卑南族", "音樂歌謠"]', '["cip_puyuma_profile"]', 'preview', 'verified_public', 'medium', 258, '[{"heading": "知識摘要", "body_zh": "公開資料將卑南族歌謠分為祭儀歌謠、休閒工作歌謠與社會時代歌謠，並舉例猴祭、大獵祭、年祭歌謠以及婦女工作團工作歌等。"}, {"heading": "來源提示", "body_zh": "CIP 卑南族頁：生活圖像—音樂跟歌謠"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_fact_0b40667f2f68', 'facts/dance_social_steps_rule', 'fact', 'dance_social_steps_rule', '舞蹈/社會角色', '公開資料指出卑南族舞蹈需依男女與年齡角色遵守相應舞步；平台展示舞蹈時應標示角色脈絡，避免把儀式舞步做成娛樂化教學。', '公開資料指出卑南族舞蹈需依男女與年齡角色遵守相應舞步；平台展示舞蹈時應標示角色脈絡，避免把儀式舞步做成娛樂化教學。', '["卑南族", "舞蹈/社會角色"]', '["cip_puyuma_profile"]', 'preview', 'verified_public', 'medium', 259, '[{"heading": "知識摘要", "body_zh": "公開資料指出卑南族舞蹈需依男女與年齡角色遵守相應舞步；平台展示舞蹈時應標示角色脈絡，避免把儀式舞步做成娛樂化教學。"}, {"heading": "來源提示", "body_zh": "CIP 卑南族頁：生活圖像—舞蹈"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_fact_2a8f3ccb1ea7', 'facts/language_contact_north_south_public', 'fact', 'language_contact_north_south_public', '族語/方言差異', '公開資料指出卑南語因部落區位與族群接觸不同而有差異，例如南面知本部落受排灣族、魯凱族語影響，北面卑南部落受阿美族語發音方式影響。', '公開資料指出卑南語因部落區位與族群接觸不同而有差異，例如南面知本部落受排灣族、魯凱族語影響，北面卑南部落受阿美族語發音方式影響。', '["卑南族", "族語/方言差異"]', '["cip_puyuma_profile"]', 'public', 'verified_public', 'low', 260, '[{"heading": "知識摘要", "body_zh": "公開資料指出卑南語因部落區位與族群接觸不同而有差異，例如南面知本部落受排灣族、魯凱族語影響，北面卑南部落受阿美族語發音方式影響。"}, {"heading": "來源提示", "body_zh": "CIP 卑南族頁：生活圖像—語言"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_fact_8da581d645f4', 'facts/kinship_clan_house_categories_public', 'fact', 'kinship_clan_house_categories_public', '親屬制度', '公開資料描述卑南族宗族與家屋觀念中，有大宗本家、小宗本家與分家等分類；平台僅可做制度摘要，不應收集或推測現代家族譜系。', '公開資料描述卑南族宗族與家屋觀念中，有大宗本家、小宗本家與分家等分類；平台僅可做制度摘要，不應收集或推測現代家族譜系。', '["卑南族", "親屬制度"]', '["cip_puyuma_profile"]', 'preview', 'verified_public', 'high', 261, '[{"heading": "知識摘要", "body_zh": "公開資料描述卑南族宗族與家屋觀念中，有大宗本家、小宗本家與分家等分類；平台僅可做制度摘要，不應收集或推測現代家族譜系。"}, {"heading": "來源提示", "body_zh": "CIP 卑南族頁：祖先的規範—親屬組織"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_fact_b74b72db76b3', 'facts/zhiben_three_clans_public_note', 'fact', 'zhiben_three_clans_public_note', '親屬制度/部落差異', '公開資料以知本社為例，提到三個氏族、共同祖廟、親族首長與會所等脈絡；此內容涉及部落內部制度，平台只做來源摘要並標記需部落審核。', '公開資料以知本社為例，提到三個氏族、共同祖廟、親族首長與會所等脈絡；此內容涉及部落內部制度，平台只做來源摘要並標記需部落審核。', '["卑南族", "親屬制度/部落差異"]', '["cip_puyuma_profile"]', 'preview', 'verified_public', 'high', 262, '[{"heading": "知識摘要", "body_zh": "公開資料以知本社為例，提到三個氏族、共同祖廟、親族首長與會所等脈絡；此內容涉及部落內部制度，平台只做來源摘要並標記需部落審核。"}, {"heading": "來源提示", "body_zh": "CIP 卑南族頁：祖先的規範—親屬組織"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_fact_2aa394160e79', 'facts/rahan_required_knowledge_public', 'fact', 'rahan_required_knowledge_public', '祭司/知識角色', '公開資料指出祭司 rahan 掌管祭祀禮儀，需熟知曆法、氣象、歷史、傳統歌謠與舞蹈；平台可列為角色摘要，不可產生祭儀主持教學。', '公開資料指出祭司 rahan 掌管祭祀禮儀，需熟知曆法、氣象、歷史、傳統歌謠與舞蹈；平台可列為角色摘要，不可產生祭儀主持教學。', '["卑南族", "祭司/知識角色"]', '["cip_puyuma_profile"]', 'preview', 'verified_public', 'high', 263, '[{"heading": "知識摘要", "body_zh": "公開資料指出祭司 rahan 掌管祭祀禮儀，需熟知曆法、氣象、歷史、傳統歌謠與舞蹈；平台可列為角色摘要，不可產生祭儀主持教學。"}, {"heading": "來源提示", "body_zh": "CIP 卑南族頁：祖先的規範—部落制度"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_fact_7714b3f9411e', 'facts/age_grade_adult_house_levels_public', 'fact', 'age_grade_adult_house_levels_public', '年齡階級', '公開資料指出進入成年會所後可分四到五個階級，成員須服從資深長者、負擔較多勞務並學習競走、摔角、野外求生與狩獵等技能。', '公開資料指出進入成年會所後可分四到五個階級，成員須服從資深長者、負擔較多勞務並學習競走、摔角、野外求生與狩獵等技能。', '["卑南族", "年齡階級"]', '["cip_puyuma_profile"]', 'preview', 'verified_public', 'medium', 264, '[{"heading": "知識摘要", "body_zh": "公開資料指出進入成年會所後可分四到五個階級，成員須服從資深長者、負擔較多勞務並學習競走、摔角、野外求生與狩獵等技能。"}, {"heading": "來源提示", "body_zh": "CIP 卑南族頁：祖先的規範—年齡階級與會所"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_fact_9eef95038a17', 'facts/modern_religion_coexistence_public', 'fact', 'modern_religion_coexistence_public', '宗教信仰/現代變遷', '公開資料指出卑南族除傳統信仰外，也有漢族信仰與西方基督宗教並存於現代生活；平台敘述現代宗教時應避免將單一信仰視為全部族人的共同狀態。', '公開資料指出卑南族除傳統信仰外，也有漢族信仰與西方基督宗教並存於現代生活；平台敘述現代宗教時應避免將單一信仰視為全部族人的共同狀態。', '["卑南族", "宗教信仰/現代變遷"]', '["cip_puyuma_profile"]', 'preview', 'verified_public', 'medium', 265, '[{"heading": "知識摘要", "body_zh": "公開資料指出卑南族除傳統信仰外，也有漢族信仰與西方基督宗教並存於現代生活；平台敘述現代宗教時應避免將單一信仰視為全部族人的共同狀態。"}, {"heading": "來源提示", "body_zh": "CIP 卑南族頁：風俗民情"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_fact_486c99e76202', 'facts/traditional_religion_revitalization_1981_public', 'fact', 'traditional_religion_revitalization_1981_public', '信仰/文化復振', '公開資料指出1981年後因傳統祭典恢復與振興，傳統宗教信仰觀念再度受到重視與討論；平台可作為文化復振時間線節點。', '公開資料指出1981年後因傳統祭典恢復與振興，傳統宗教信仰觀念再度受到重視與討論；平台可作為文化復振時間線節點。', '["卑南族", "信仰/文化復振"]', '["cip_puyuma_profile"]', 'preview', 'verified_public', 'medium', 266, '[{"heading": "知識摘要", "body_zh": "公開資料指出1981年後因傳統祭典恢復與振興，傳統宗教信仰觀念再度受到重視與討論；平台可作為文化復振時間線節點。"}, {"heading": "來源提示", "body_zh": "CIP 卑南族頁：風俗民情"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_fact_cbca57b42761', 'facts/millet_harvest_swing_public_rule', 'fact', 'millet_harvest_swing_public_rule', '祭儀/公開活動', '公開資料提到部分部落在小米收穫祭時於會所廣場搭鞦韆架，並賦予為農作祈福的象徵意義；平台可作文化活動介紹，但不替代部落祭儀說明。', '公開資料提到部分部落在小米收穫祭時於會所廣場搭鞦韆架，並賦予為農作祈福的象徵意義；平台可作文化活動介紹，但不替代部落祭儀說明。', '["卑南族", "祭儀/公開活動"]', '["cip_puyuma_profile"]', 'preview', 'verified_public', 'medium', 267, '[{"heading": "知識摘要", "body_zh": "公開資料提到部分部落在小米收穫祭時於會所廣場搭鞦韆架，並賦予為農作祈福的象徵意義；平台可作文化活動介紹，但不替代部落祭儀說明。"}, {"heading": "來源提示", "body_zh": "CIP 卑南族頁：風俗民情—小米收穫祭"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_fact_45527d576ec2', 'facts/annual_festival_preparation_public', 'fact', 'annual_festival_preparation_public', '年祭/準備工作', '公開資料指出年祭前族人會編織花環、準備食物與釀酒，部落周圍也會設立路障並整修會所、設立祭壇與刺猴祭壇；平台需避免公開禁忌或操作細節。', '公開資料指出年祭前族人會編織花環、準備食物與釀酒，部落周圍也會設立路障並整修會所、設立祭壇與刺猴祭壇；平台需避免公開禁忌或操作細節。', '["卑南族", "年祭/準備工作"]', '["cip_puyuma_profile"]', 'preview', 'verified_public', 'high', 268, '[{"heading": "知識摘要", "body_zh": "公開資料指出年祭前族人會編織花環、準備食物與釀酒，部落周圍也會設立路障並整修會所、設立祭壇與刺猴祭壇；平台需避免公開禁忌或操作細節。"}, {"heading": "來源提示", "body_zh": "CIP 卑南族頁：風俗民情—年祭"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_fact_431b5659267b', 'facts/monkey_rite_exorcism_public', 'fact', 'monkey_rite_exorcism_public', '少年年祭/猴祭', '公開資料指出傳統猴祭前一晚，青少年有赤裸上身、塗炭灰、持芭蕉葉到各戶驅除邪魔的脈絡；平台只可摘要，不可做成仿作或教學內容。', '公開資料指出傳統猴祭前一晚，青少年有赤裸上身、塗炭灰、持芭蕉葉到各戶驅除邪魔的脈絡；平台只可摘要，不可做成仿作或教學內容。', '["卑南族", "少年年祭/猴祭"]', '["cip_puyuma_profile"]', 'preview', 'verified_public', 'high', 269, '[{"heading": "知識摘要", "body_zh": "公開資料指出傳統猴祭前一晚，青少年有赤裸上身、塗炭灰、持芭蕉葉到各戶驅除邪魔的脈絡；平台只可摘要，不可做成仿作或教學內容。"}, {"heading": "來源提示", "body_zh": "CIP 卑南族頁：風俗民情—猴祭"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_fact_93583b903415', 'facts/hunting_rite_return_ceremony_public', 'fact', 'hunting_rite_return_ceremony_public', '大獵祭', '公開資料指出大獵祭活動結束時，部落婦女會於部落外以竹子搭建凱旋門等待，男子回部落後由婦女更換禮服並共同慶功與慰問喪家。', '公開資料指出大獵祭活動結束時，部落婦女會於部落外以竹子搭建凱旋門等待，男子回部落後由婦女更換禮服並共同慶功與慰問喪家。', '["卑南族", "大獵祭"]', '["cip_puyuma_profile"]', 'preview', 'verified_public', 'medium', 270, '[{"heading": "知識摘要", "body_zh": "公開資料指出大獵祭活動結束時，部落婦女會於部落外以竹子搭建凱旋門等待，男子回部落後由婦女更換禮服並共同慶功與慰問喪家。"}, {"heading": "來源提示", "body_zh": "CIP 卑南族頁：風俗民情—大獵祭"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_fact_2b0cff872566', 'facts/joint_festival_decision_body_public', 'fact', 'joint_festival_decision_body_public', '聯合年祭', '公開資料指出聯合年祭舉辦時間不定，由部落聯合會議決定，並由卑南族各部落輪流舉辦；平台不得自行公告日期，應連結部落或官方公告。', '公開資料指出聯合年祭舉辦時間不定，由部落聯合會議決定，並由卑南族各部落輪流舉辦；平台不得自行公告日期，應連結部落或官方公告。', '["卑南族", "聯合年祭"]', '["cip_puyuma_profile"]', 'public', 'verified_public', 'low', 271, '[{"heading": "知識摘要", "body_zh": "公開資料指出聯合年祭舉辦時間不定，由部落聯合會議決定，並由卑南族各部落輪流舉辦；平台不得自行公告日期，應連結部落或官方公告。"}, {"heading": "來源提示", "body_zh": "CIP 卑南族頁：風俗民情—聯合年祭"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_fact_c373c440b70b', 'facts/formosanbank_epark_audio_failed_handling', 'fact', 'formosanbank_epark_audio_failed_handling', '族語語料/音檔治理', 'FormosanBank ePark README 說明有 failed_audio.csv 與 update_audio.py，用於記錄與移除下載失敗音檔相關標籤；平台建立語音 manifest 時應保留 failed/skipped 狀態，不可假設所有音檔都有效。', 'FormosanBank ePark README 說明有 failed_audio.csv 與 update_audio.py，用於記錄與移除下載失敗音檔相關標籤；平台建立語音 manifest 時應保留 failed/skipped 狀態，不可假設所有音檔都有效。', '["卑南族", "族語語料/音檔治理"]', '["formosanbank_epark_readme"]', 'public', 'verified_public', 'low', 272, '[{"heading": "知識摘要", "body_zh": "FormosanBank ePark README 說明有 failed_audio.csv 與 update_audio.py，用於記錄與移除下載失敗音檔相關標籤；平台建立語音 manifest 時應保留 failed/skipped 狀態，不可假設所有音檔都有效。"}, {"heading": "來源提示", "body_zh": "FormosanBank ePark README：failed_audio.csv、update_audio.py"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_fact_80a8c39aca36', 'facts/formosanbank_puyuma_orthography_note', 'fact', 'formosanbank_puyuma_orthography_note', '族語語料/正字法', 'FormosanBank ePark README 指出九階教材的 Puyuma 使用 Ortho94 轉換表，其他多數 Puyuma 子語料常見 Ortho113；平台匯入族語資料時應保留來源正字法欄位與標準化版本欄位。', 'FormosanBank ePark README 指出九階教材的 Puyuma 使用 Ortho94 轉換表，其他多數 Puyuma 子語料常見 Ortho113；平台匯入族語資料時應保留來源正字法欄位與標準化版本欄位。', '["卑南族", "族語語料/正字法"]', '["formosanbank_epark_readme"]', 'public', 'verified_public', 'low', 273, '[{"heading": "知識摘要", "body_zh": "FormosanBank ePark README 指出九階教材的 Puyuma 使用 Ortho94 轉換表，其他多數 Puyuma 子語料常見 Ortho113；平台匯入族語資料時應保留來源正字法欄位與標準化版本欄位。"}, {"heading": "來源提示", "body_zh": "FormosanBank ePark README：Standardize XML, Part 2; Also add IPA"}]');
