INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_fact_9843549f9bae', 'facts/annual_festival_roadblocks_altars_public_sensitive', 'fact', 'annual_festival_roadblocks_altars_public_sensitive', '年祭', '公開資料提到年祭前可能有花環、食物、釀酒、路障、整修會所、祭壇等準備；平台只可作概述，不得變成辦理流程。', '公開資料提到年祭前可能有花環、食物、釀酒、路障、整修會所、祭壇等準備；平台只可作概述，不得變成辦理流程。', '["卑南族", "年祭"]', '["cip_puyuma_profile"]', 'preview', 'verified_public', 'high', 305, '[{"heading": "知識摘要", "body_zh": "公開資料提到年祭前可能有花環、食物、釀酒、路障、整修會所、祭壇等準備；平台只可作概述，不得變成辦理流程。"}, {"heading": "來源提示", "body_zh": "CIP line 306"}]');
