INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_fact_1cb4a27afc58', 'facts/hunting_rite_three_day_public', 'fact', 'hunting_rite_three_day_public', '大獵祭', '公開資料描述現代大獵祭已改為定點活動，並於12月下旬連續數日進行野地紮營與技能教導；實際日期與內容以部落公告為準。', '公開資料描述現代大獵祭已改為定點活動，並於12月下旬連續數日進行野地紮營與技能教導；實際日期與內容以部落公告為準。', '["卑南族", "大獵祭"]', '["cip_puyuma_profile"]', 'preview', 'verified_public', 'high', 307, '[{"heading": "知識摘要", "body_zh": "公開資料描述現代大獵祭已改為定點活動，並於12月下旬連續數日進行野地紮營與技能教導；實際日期與內容以部落公告為準。"}, {"heading": "來源提示", "body_zh": "CIP lines 310-311"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_fact_893870f62a9a', 'facts/joint_festival_rotating_public', 'fact', 'joint_festival_rotating_public', '聯合年祭', '公開資料指出聯合年祭自1982年前後逐漸發展，由各部落輪流舉辦，包含歌舞與競賽等公開活動。', '公開資料指出聯合年祭自1982年前後逐漸發展，由各部落輪流舉辦，包含歌舞與競賽等公開活動。', '["卑南族", "聯合年祭"]', '["cip_puyuma_profile"]', 'preview', 'verified_public', 'medium', 308, '[{"heading": "知識摘要", "body_zh": "公開資料指出聯合年祭自1982年前後逐漸發展，由各部落輪流舉辦，包含歌舞與競賽等公開活動。"}, {"heading": "來源提示", "body_zh": "CIP lines 313"}]');
