INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_vocab_e4222d2b253d', 'language/puyuma/audio/puyuma-audio-b04e215f3e73', 'vocabulary', 'puyuma-audio-b04e215f3e73', '大家好。今天老師要教大家食物的南王卑南語怎麼說。', '南王卑南語：inabayan! garem i palaladam ku kanmu dra kemuda ta temarapuyuma marengay kana akanan.', 'inabayan! garem i palaladam ku kanmu dra kemuda ta temarapuyuma marengay kana akanan. / 大家好。今天老師要教大家食物的南王卑南語怎麼說。 / Hello everyone. Today I am going to teach you how to say food in Puyuma.', '["卑南語", "語詞庫", "音檔", "南王卑南語", "問候語", "inabayan! garem i palaladam ku kanmu dra kemuda ta temarapuyuma marengay kana akanan.", "大家好。今天老師要教大家食物的南王卑南語怎麼說。"]', '["formosanbank_epark"]', 'public', 'approved_for_public_learning_preview_subset', 'low', 400, '[{"heading": "族語", "body_zh": "inabayan! garem i palaladam ku kanmu dra kemuda ta temarapuyuma marengay kana akanan."}, {"heading": "中文", "body_zh": "大家好。今天老師要教大家食物的南王卑南語怎麼說。"}, {"heading": "音檔", "body_zh": "https://web.klokah.tw/text/sound/27443/455710.mp3"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_vocab_ec31e55a0cb2', 'language/puyuma/audio/puyuma-audio-3459f9d2c9ba', 'vocabulary', 'puyuma-audio-3459f9d2c9ba', '你聽得懂老師的話嗎?', '南王卑南語：malradram yu kilrengaw kananku nirengayan?', 'malradram yu kilrengaw kananku nirengayan? / 你聽得懂老師的話嗎? / Do you understand what the teacher says?', '["卑南語", "語詞庫", "音檔", "南王卑南語", "教室與學校", "malradram yu kilrengaw kananku nirengayan?", "你聽得懂老師的話嗎?"]', '["formosanbank_epark"]', 'public', 'approved_for_public_learning_preview_subset', 'low', 400, '[{"heading": "族語", "body_zh": "malradram yu kilrengaw kananku nirengayan?"}, {"heading": "中文", "body_zh": "你聽得懂老師的話嗎?"}, {"heading": "音檔", "body_zh": "https://web.klokah.tw/text/sound/27443/455711.mp3"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_vocab_080be92fe786', 'language/puyuma/audio/puyuma-audio-c906ef49ba1a', 'vocabulary', 'puyuma-audio-c906ef49ba1a', '老師，我不懂。可以再說一次嗎?', '南王卑南語：sinsi, adri ku malradram. karuwa yu masalr marengay?', 'sinsi, adri ku malradram. karuwa yu masalr marengay? / 老師，我不懂。可以再說一次嗎? / I don’t understand. Can you repeat it again?', '["卑南語", "語詞庫", "音檔", "南王卑南語", "教室與學校", "sinsi, adri ku malradram. karuwa yu masalr marengay?", "老師，我不懂。可以再說一次嗎?"]', '["formosanbank_epark"]', 'public', 'approved_for_public_learning_preview_subset', 'low', 400, '[{"heading": "族語", "body_zh": "sinsi, adri ku malradram. karuwa yu masalr marengay?"}, {"heading": "中文", "body_zh": "老師，我不懂。可以再說一次嗎?"}, {"heading": "音檔", "body_zh": "https://web.klokah.tw/text/sound/27443/455712.mp3"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_vocab_7ba1d50ee7db', 'language/puyuma/audio/puyuma-audio-f9f0a43ba400', 'vocabulary', 'puyuma-audio-f9f0a43ba400', '我聽不到，可以大聲一點嗎?', '南王卑南語：adri ku kilrengaw. karuwa yu kematrina driya?', 'adri ku kilrengaw. karuwa yu kematrina driya? / 我聽不到，可以大聲一點嗎? / I can’t hear you, can you speak louder?', '["卑南語", "語詞庫", "音檔", "南王卑南語", "教室與學校", "adri ku kilrengaw. karuwa yu kematrina driya?", "我聽不到，可以大聲一點嗎?"]', '["formosanbank_epark"]', 'public', 'approved_for_public_learning_preview_subset', 'low', 400, '[{"heading": "族語", "body_zh": "adri ku kilrengaw. karuwa yu kematrina driya?"}, {"heading": "中文", "body_zh": "我聽不到，可以大聲一點嗎?"}, {"heading": "音檔", "body_zh": "https://web.klokah.tw/text/sound/27443/455713.mp3"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_vocab_b4b9fa38d07f', 'language/puyuma/audio/puyuma-audio-8f66055d0da1', 'vocabulary', 'puyuma-audio-8f66055d0da1', '請看這裡! 跟著我唸一遍。', '南王卑南語：nauwi driya kadri! kurenangi ku emaip pariyasalr.', 'nauwi driya kadri! kurenangi ku emaip pariyasalr. / 請看這裡! 跟著我唸一遍。 / Look here, please! Repeat after me.', '["卑南語", "語詞庫", "音檔", "南王卑南語", "教室與學校", "nauwi driya kadri! kurenangi ku emaip pariyasalr.", "請看這裡! 跟著我唸一遍。"]', '["formosanbank_epark"]', 'public', 'approved_for_public_learning_preview_subset', 'low', 400, '[{"heading": "族語", "body_zh": "nauwi driya kadri! kurenangi ku emaip pariyasalr."}, {"heading": "中文", "body_zh": "請看這裡! 跟著我唸一遍。"}, {"heading": "音檔", "body_zh": "https://web.klokah.tw/text/sound/27443/455714.mp3"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_vocab_9fcc4c3a32c7', 'language/puyuma/audio/puyuma-audio-f47948944915', 'vocabulary', 'puyuma-audio-f47948944915', '你唸得很好。', '南王卑南語：inaba nu inaipan.', 'inaba nu inaipan. / 你唸得很好。 / You read it very well.', '["卑南語", "語詞庫", "音檔", "南王卑南語", "教室與學校", "inaba nu inaipan.", "你唸得很好。"]', '["formosanbank_epark"]', 'public', 'approved_for_public_learning_preview_subset', 'low', 400, '[{"heading": "族語", "body_zh": "inaba nu inaipan."}, {"heading": "中文", "body_zh": "你唸得很好。"}, {"heading": "音檔", "body_zh": "https://web.klokah.tw/text/sound/27443/455715.mp3"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_vocab_cd83b2257d29', 'language/puyuma/audio/puyuma-audio-8ec78ce2da04', 'vocabulary', 'puyuma-audio-8ec78ce2da04', '再唸一次。請大聲一點。', '南王卑南語：asalr driya maip. katrinayu driya.', 'asalr driya maip. katrinayu driya. / 再唸一次。請大聲一點。 / Read it again. Please speak louder.', '["卑南語", "語詞庫", "音檔", "南王卑南語", "教室與學校", "asalr driya maip. katrinayu driya.", "再唸一次。請大聲一點。"]', '["formosanbank_epark"]', 'public', 'approved_for_public_learning_preview_subset', 'low', 400, '[{"heading": "族語", "body_zh": "asalr driya maip. katrinayu driya."}, {"heading": "中文", "body_zh": "再唸一次。請大聲一點。"}, {"heading": "音檔", "body_zh": "https://web.klokah.tw/text/sound/27443/455716.mp3"}]');
