INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_vocab_7c1a7179841d', 'language/puyuma/audio/puyuma-audio-0df27f692e48', 'vocabulary', 'puyuma-audio-0df27f692e48', '老師，我忘了帶筆。', '南王卑南語：sinsi, abalu ku kemasu dra tratruri.', 'sinsi, abalu ku kemasu dra tratruri. / 老師，我忘了帶筆。 / I forgot to bring my pen.', '["卑南語", "語詞庫", "音檔", "南王卑南語", "教室與學校", "sinsi, abalu ku kemasu dra tratruri.", "老師，我忘了帶筆。"]', '["formosanbank_epark"]', 'public', 'approved_for_public_learning_preview_subset', 'low', 400, '[{"heading": "族語", "body_zh": "sinsi, abalu ku kemasu dra tratruri."}, {"heading": "中文", "body_zh": "老師，我忘了帶筆。"}, {"heading": "音檔", "body_zh": "https://web.klokah.tw/text/sound/27443/455721.mp3"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_vocab_b78fc7f230e8', 'language/puyuma/audio/puyuma-audio-7b7185613f33', 'vocabulary', 'puyuma-audio-7b7185613f33', '請把橡皮擦拿出來。', '南王卑南語：pupatraranu driya na iyasaus.', 'pupatraranu driya na iyasaus. / 請把橡皮擦拿出來。 / Please take out the eraser.', '["卑南語", "語詞庫", "音檔", "南王卑南語", "教室與學校", "pupatraranu driya na iyasaus.", "請把橡皮擦拿出來。"]', '["formosanbank_epark"]', 'public', 'approved_for_public_learning_preview_subset', 'low', 400, '[{"heading": "族語", "body_zh": "pupatraranu driya na iyasaus."}, {"heading": "中文", "body_zh": "請把橡皮擦拿出來。"}, {"heading": "音檔", "body_zh": "https://web.klokah.tw/text/sound/27443/455722.mp3"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_vocab_d27b63157ed9', 'language/puyuma/audio/puyuma-audio-3c05e63b6315', 'vocabulary', 'puyuma-audio-3c05e63b6315', '老師，我忘了帶橡皮擦。', '南王卑南語：sinsi, abalu ku kemasu dra iyasaus.', 'sinsi, abalu ku kemasu dra iyasaus. / 老師，我忘了帶橡皮擦。 / I forgot to bring my eraser.', '["卑南語", "語詞庫", "音檔", "南王卑南語", "教室與學校", "sinsi, abalu ku kemasu dra iyasaus.", "老師，我忘了帶橡皮擦。"]', '["formosanbank_epark"]', 'public', 'approved_for_public_learning_preview_subset', 'low', 400, '[{"heading": "族語", "body_zh": "sinsi, abalu ku kemasu dra iyasaus."}, {"heading": "中文", "body_zh": "老師，我忘了帶橡皮擦。"}, {"heading": "音檔", "body_zh": "https://web.klokah.tw/text/sound/27443/455723.mp3"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_vocab_2a6fa674af2b', 'language/puyuma/audio/puyuma-audio-38e4d63b1e3e', 'vocabulary', 'puyuma-audio-38e4d63b1e3e', '請跟旁邊同學借橡皮擦。', '南王卑南語：kibulas driya kan tu iyasaus kana risarisan i saninin.', 'kibulas driya kan tu iyasaus kana risarisan i saninin. / 請跟旁邊同學借橡皮擦。 / Please borrow erasers from your classmates.', '["卑南語", "語詞庫", "音檔", "南王卑南語", "教室與學校", "kibulas driya kan tu iyasaus kana risarisan i saninin.", "請跟旁邊同學借橡皮擦。"]', '["formosanbank_epark"]', 'public', 'approved_for_public_learning_preview_subset', 'low', 400, '[{"heading": "族語", "body_zh": "kibulas driya kan tu iyasaus kana risarisan i saninin."}, {"heading": "中文", "body_zh": "請跟旁邊同學借橡皮擦。"}, {"heading": "音檔", "body_zh": "https://web.klokah.tw/text/sound/27443/455724.mp3"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_vocab_952422062e05', 'language/puyuma/audio/puyuma-audio-17126d46fe53', 'vocabulary', 'puyuma-audio-17126d46fe53', '借我橡皮擦好嗎?', '南王卑南語：pabulasi ku driya dra iyasaus. maw?', 'pabulasi ku driya dra iyasaus. maw? / 借我橡皮擦好嗎? / Can I borrow your eraser?', '["卑南語", "語詞庫", "音檔", "南王卑南語", "教室與學校", "pabulasi ku driya dra iyasaus. maw?", "借我橡皮擦好嗎?"]', '["formosanbank_epark"]', 'public', 'approved_for_public_learning_preview_subset', 'low', 400, '[{"heading": "族語", "body_zh": "pabulasi ku driya dra iyasaus. maw?"}, {"heading": "中文", "body_zh": "借我橡皮擦好嗎?"}, {"heading": "音檔", "body_zh": "https://web.klokah.tw/text/sound/27443/455725.mp3"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_vocab_3abaabf7ba82', 'language/puyuma/audio/puyuma-audio-5c9375318083', 'vocabulary', 'puyuma-audio-5c9375318083', '我們家住在知本。', '知本卑南語：ulra i Katratripulr niyam ruma’.', 'ulra i Katratripulr niyam ruma’. / 我們家住在知本。 / Our family lives in Katratripulr.', '["卑南語", "語詞庫", "音檔", "知本卑南語", "教室與學校", "ulra i Katratripulr niyam ruma’.", "我們家住在知本。"]', '["formosanbank_epark"]', 'public', 'approved_for_public_learning_preview_subset', 'low', 400, '[{"heading": "族語", "body_zh": "ulra i Katratripulr niyam ruma’."}, {"heading": "中文", "body_zh": "我們家住在知本。"}, {"heading": "音檔", "body_zh": "https://web.klokah.tw/text/sound/35733/556244.mp3"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_vocab_f537b925f7a9', 'language/puyuma/audio/puyuma-audio-e393a3d0412b', 'vocabulary', 'puyuma-audio-e393a3d0412b', '上課的時候，老師教我們數字的族語。', '知本卑南語：temakakesi mi lra, na sinsi pananadam kananta piningaiyan na aiyupan.', 'temakakesi mi lra, na sinsi pananadam kananta piningaiyan na aiyupan. / 上課的時候，老師教我們數字的族語。 / In class, the teacher taught us the Pinuyumayan language of numbers.', '["卑南語", "語詞庫", "音檔", "知本卑南語", "教室與學校", "temakakesi mi lra, na sinsi pananadam kananta piningaiyan na aiyupan.", "上課的時候，老師教我們數字的族語。"]', '["formosanbank_epark"]', 'public', 'approved_for_public_learning_preview_subset', 'low', 400, '[{"heading": "族語", "body_zh": "temakakesi mi lra, na sinsi pananadam kananta piningaiyan na aiyupan."}, {"heading": "中文", "body_zh": "上課的時候，老師教我們數字的族語。"}, {"heading": "音檔", "body_zh": "https://web.klokah.tw/text/sound/35725/556140.mp3"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_vocab_5170a455ef82', 'language/puyuma/audio/puyuma-audio-ebf64aa99678', 'vocabulary', 'puyuma-audio-ebf64aa99678', '我今天七點到學校。', '知本卑南語：harem kana wari pituwa tuki mu medek ku i kungkuwan.', 'harem kana wari pituwa tuki mu medek ku i kungkuwan. / 我今天七點到學校。 / I arrived at school at seven today.', '["卑南語", "語詞庫", "音檔", "知本卑南語", "教室與學校", "harem kana wari pituwa tuki mu medek ku i kungkuwan.", "我今天七點到學校。"]', '["formosanbank_epark"]', 'public', 'approved_for_public_learning_preview_subset', 'low', 400, '[{"heading": "族語", "body_zh": "harem kana wari pituwa tuki mu medek ku i kungkuwan."}, {"heading": "中文", "body_zh": "我今天七點到學校。"}, {"heading": "音檔", "body_zh": "https://web.klokah.tw/text/sound/35725/556137.mp3"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_vocab_ce3e6c55c072', 'language/puyuma/audio/puyuma-audio-ecd06c07e0fd', 'vocabulary', 'puyuma-audio-ecd06c07e0fd', '上課了，老師走進教室，班長說:「起立!敬禮!」', '知本卑南語：puwateha mi lra temakesi zi, musavak na sinsi i takakesiyan, na niyam kemakezeng na sasevangan marengay, “katikeriz! sungal!” kema marengay.', 'puwateha mi lra temakesi zi, musavak na sinsi i takakesiyan, na niyam kemakezeng na sasevangan marengay, “katikeriz! sungal!” kema marengay. / 上課了，老師走進教室，班長說:「起立!敬禮!」 / It’s time for class, the teacher walked into the classroom, and the monitor said: “Stand up! Salute!”', '["卑南語", "語詞庫", "音檔", "知本卑南語", "教室與學校", "puwateha mi lra temakesi zi, musavak na sinsi i takakesiyan, na niyam kemakezeng na sasevangan marengay, “katikeriz! sungal!” kema marengay.", "上課了，老師走進教室，班長說:「起立!敬禮!」"]', '["formosanbank_epark"]', 'public', 'approved_for_public_learning_preview_subset', 'low', 400, '[{"heading": "族語", "body_zh": "puwateha mi lra temakesi zi, musavak na sinsi i takakesiyan, na niyam kemakezeng na sasevangan marengay, “katikeriz! sungal!” kema marengay."}, {"heading": "中文", "body_zh": "上課了，老師走進教室，班長說:「起立!敬禮!」"}, {"heading": "音檔", "body_zh": "https://web.klokah.tw/text/sound/35725/556138.mp3"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_vocab_75f84be07133', 'language/puyuma/audio/puyuma-audio-45dc39676f0e', 'vocabulary', 'puyuma-audio-45dc39676f0e', '我們大聲的說:「老師好。」', '知本卑南語：kematamuni mi marengay, “’inavayan sinsi.”', 'kematamuni mi marengay, “’inavayan sinsi.” / 我們大聲的說:「老師好。」 / We said loudly, “Hi, teacher.”', '["卑南語", "語詞庫", "音檔", "知本卑南語", "問候語", "kematamuni mi marengay, “’inavayan sinsi.”", "我們大聲的說:「老師好。」"]', '["formosanbank_epark"]', 'public', 'approved_for_public_learning_preview_subset', 'low', 400, '[{"heading": "族語", "body_zh": "kematamuni mi marengay, “’inavayan sinsi.”"}, {"heading": "中文", "body_zh": "我們大聲的說:「老師好。」"}, {"heading": "音檔", "body_zh": "https://web.klokah.tw/text/sound/35725/556139.mp3"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_vocab_a6f75462eeac', 'language/puyuma/audio/puyuma-audio-d8bf21308421', 'vocabulary', 'puyuma-audio-d8bf21308421', '我們跟著老師唸，我們唱了數字歌。', '知本卑南語：miturus mi kana sinsi miyup, semenay mi kana senay na aiyupan.', 'miturus mi kana sinsi miyup, semenay mi kana senay na aiyupan. / 我們跟著老師唸，我們唱了數字歌。 / We followed the teacher to read, we sang the number song.', '["卑南語", "語詞庫", "音檔", "知本卑南語", "教室與學校", "miturus mi kana sinsi miyup, semenay mi kana senay na aiyupan.", "我們跟著老師唸，我們唱了數字歌。"]', '["formosanbank_epark"]', 'public', 'approved_for_public_learning_preview_subset', 'low', 400, '[{"heading": "族語", "body_zh": "miturus mi kana sinsi miyup, semenay mi kana senay na aiyupan."}, {"heading": "中文", "body_zh": "我們跟著老師唸，我們唱了數字歌。"}, {"heading": "音檔", "body_zh": "https://web.klokah.tw/text/sound/35725/556141.mp3"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_vocab_b991a5d167d3', 'language/puyuma/audio/puyuma-audio-94508008f8a6', 'vocabulary', 'puyuma-audio-94508008f8a6', '我學會好多族語。', '知本卑南語：sazu aku ninadaman kananta piningaiyan.', 'sazu aku ninadaman kananta piningaiyan. / 我學會好多族語。 / I have learned many Pinuyumayan languages.', '["卑南語", "語詞庫", "音檔", "知本卑南語", "教室與學校", "sazu aku ninadaman kananta piningaiyan.", "我學會好多族語。"]', '["formosanbank_epark"]', 'public', 'approved_for_public_learning_preview_subset', 'low', 400, '[{"heading": "族語", "body_zh": "sazu aku ninadaman kananta piningaiyan."}, {"heading": "中文", "body_zh": "我學會好多族語。"}, {"heading": "音檔", "body_zh": "https://web.klokah.tw/text/sound/35725/556142.mp3"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_vocab_dac52b082f36', 'language/puyuma/audio/puyuma-audio-de7a5ff6d36d', 'vocabulary', 'puyuma-audio-de7a5ff6d36d', '我天天上學，我天天學族語，我要講給媽媽聽。', '知本卑南語：kana wariwari ziya mukakuwa ku i kungkuwan, kana wariwari ziya mu menadanadam ku kananta piningaiyan, rarengay ku pakinger kani ina.', 'kana wariwari ziya mukakuwa ku i kungkuwan, kana wariwari ziya mu menadanadam ku kananta piningaiyan, rarengay ku pakinger kani ina. / 我天天上學，我天天學族語，我要講給媽媽聽。 / I go to school every day, I learn the Pinuyumayan language every day, and I want to tell my mother.', '["卑南語", "語詞庫", "音檔", "知本卑南語", "教室與學校", "kana wariwari ziya mukakuwa ku i kungkuwan, kana wariwari ziya mu menadanadam ku kananta piningaiyan, rarengay ku pakinger kani ina.", "我天天上學，我天天學族語，我要講給媽媽聽。"]', '["formosanbank_epark"]', 'public', 'approved_for_public_learning_preview_subset', 'low', 400, '[{"heading": "族語", "body_zh": "kana wariwari ziya mukakuwa ku i kungkuwan, kana wariwari ziya mu menadanadam ku kananta piningaiyan, rarengay ku pakinger kani ina."}, {"heading": "中文", "body_zh": "我天天上學，我天天學族語，我要講給媽媽聽。"}, {"heading": "音檔", "body_zh": "https://web.klokah.tw/text/sound/35725/556143.mp3"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_vocab_b886064fc903', 'language/puyuma/audio/puyuma-audio-2d0099983af8', 'vocabulary', 'puyuma-audio-2d0099983af8', '我的名字是Atēk。', '知本卑南語：i Atēk aku ngadan.', 'i Atēk aku ngadan. / 我的名字是Atēk。 / My name is Atēk.', '["卑南語", "語詞庫", "音檔", "知本卑南語", "教室與學校", "i Atēk aku ngadan.", "我的名字是Atēk。"]', '["formosanbank_epark"]', 'public', 'approved_for_public_learning_preview_subset', 'low', 400, '[{"heading": "族語", "body_zh": "i Atēk aku ngadan."}, {"heading": "中文", "body_zh": "我的名字是Atēk。"}, {"heading": "音檔", "body_zh": "https://web.klokah.tw/text/sound/35729/556191.mp3"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_vocab_8eb4e2dbc558', 'language/puyuma/audio/puyuma-audio-1cdcfb554bb2', 'vocabulary', 'puyuma-audio-1cdcfb554bb2', '我爸爸的名字是Kaliya。', '知本卑南語：tu ngadan ni malri mu maw i Kaliya.', 'tu ngadan ni malri mu maw i Kaliya. / 我爸爸的名字是Kaliya。 / My dad’s name is Kaliya.', '["卑南語", "語詞庫", "音檔", "知本卑南語", "教室與學校", "tu ngadan ni malri mu maw i Kaliya.", "我爸爸的名字是Kaliya。"]', '["formosanbank_epark"]', 'public', 'approved_for_public_learning_preview_subset', 'low', 400, '[{"heading": "族語", "body_zh": "tu ngadan ni malri mu maw i Kaliya."}, {"heading": "中文", "body_zh": "我爸爸的名字是Kaliya。"}, {"heading": "音檔", "body_zh": "https://web.klokah.tw/text/sound/35729/556192.mp3"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_vocab_24d092d95ba1', 'language/puyuma/audio/puyuma-audio-dd1bff32ef72', 'vocabulary', 'puyuma-audio-dd1bff32ef72', '我媽媽的名字是Lapi。', '知本卑南語：tu ngadan ni nani mu maw i Lapi.', 'tu ngadan ni nani mu maw i Lapi. / 我媽媽的名字是Lapi。 / My mother’s name is Lapi.', '["卑南語", "語詞庫", "音檔", "知本卑南語", "教室與學校", "tu ngadan ni nani mu maw i Lapi.", "我媽媽的名字是Lapi。"]', '["formosanbank_epark"]', 'public', 'approved_for_public_learning_preview_subset', 'low', 400, '[{"heading": "族語", "body_zh": "tu ngadan ni nani mu maw i Lapi."}, {"heading": "中文", "body_zh": "我媽媽的名字是Lapi。"}, {"heading": "音檔", "body_zh": "https://web.klokah.tw/text/sound/35729/556193.mp3"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_vocab_154a697b932d', 'language/puyuma/audio/puyuma-audio-23c2fbbf4341', 'vocabulary', 'puyuma-audio-23c2fbbf4341', '我今年10歲。', '知本卑南語：muketrep lra ku ’ami harem.', 'muketrep lra ku ’ami harem. / 我今年10歲。 / I am 10 years old.', '["卑南語", "語詞庫", "音檔", "知本卑南語", "教室與學校", "muketrep lra ku ’ami harem.", "我今年10歲。"]', '["formosanbank_epark"]', 'public', 'approved_for_public_learning_preview_subset', 'low', 400, '[{"heading": "族語", "body_zh": "muketrep lra ku ’ami harem."}, {"heading": "中文", "body_zh": "我今年10歲。"}, {"heading": "音檔", "body_zh": "https://web.klokah.tw/text/sound/35729/556194.mp3"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_vocab_0d93ab57ce78', 'language/puyuma/audio/puyuma-audio-7a6d8fcc6929', 'vocabulary', 'puyuma-audio-7a6d8fcc6929', '我有一個哥哥，他叫Uking，他今年11歲。', '知本卑南語：ulra i valri na ma’inay a sasa, tu ngadan maw i Uking, i intaw harem mu muketrep misama’ za saya tu ’ami.', 'ulra i valri na ma’inay a sasa, tu ngadan maw i Uking, i intaw harem mu muketrep misama’ za saya tu ’ami. / 我有一個哥哥，他叫Uking，他今年11歲。 / I have a brother, his name is Uking, he is 11 years old.', '["卑南語", "語詞庫", "音檔", "知本卑南語", "教室與學校", "ulra i valri na ma’inay a sasa, tu ngadan maw i Uking, i intaw harem mu muketrep misama’ za saya tu ’ami.", "我有一個哥哥，他叫Uking，他今年11歲。"]', '["formosanbank_epark"]', 'public', 'approved_for_public_learning_preview_subset', 'low', 400, '[{"heading": "族語", "body_zh": "ulra i valri na ma’inay a sasa, tu ngadan maw i Uking, i intaw harem mu muketrep misama’ za saya tu ’ami."}, {"heading": "中文", "body_zh": "我有一個哥哥，他叫Uking，他今年11歲。"}, {"heading": "音檔", "body_zh": "https://web.klokah.tw/text/sound/35729/556195.mp3"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_vocab_db5a5ac8e153', 'language/puyuma/audio/puyuma-audio-27ad7b13ee68', 'vocabulary', 'puyuma-audio-27ad7b13ee68', '我們在同一間學校讀書。', '知本卑南語：salrangan mi temakesi kana saya kungkuwan.', 'salrangan mi temakesi kana saya kungkuwan. / 我們在同一間學校讀書。 / We study in the same school.', '["卑南語", "語詞庫", "音檔", "知本卑南語", "教室與學校", "salrangan mi temakesi kana saya kungkuwan.", "我們在同一間學校讀書。"]', '["formosanbank_epark"]', 'public', 'approved_for_public_learning_preview_subset', 'low', 400, '[{"heading": "族語", "body_zh": "salrangan mi temakesi kana saya kungkuwan."}, {"heading": "中文", "body_zh": "我們在同一間學校讀書。"}, {"heading": "音檔", "body_zh": "https://web.klokah.tw/text/sound/35729/556196.mp3"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_vocab_14febcc14db8', 'language/puyuma/audio/puyuma-audio-96aa43762826', 'vocabulary', 'puyuma-audio-96aa43762826', '我和哥哥都喜歡唱歌。', '知本卑南語：inku za i valri sahar mi semenay.', 'inku za i valri sahar mi semenay. / 我和哥哥都喜歡唱歌。 / Both my brother and I like to sing.', '["卑南語", "語詞庫", "音檔", "知本卑南語", "教室與學校", "inku za i valri sahar mi semenay.", "我和哥哥都喜歡唱歌。"]', '["formosanbank_epark"]', 'public', 'approved_for_public_learning_preview_subset', 'low', 400, '[{"heading": "族語", "body_zh": "inku za i valri sahar mi semenay."}, {"heading": "中文", "body_zh": "我和哥哥都喜歡唱歌。"}, {"heading": "音檔", "body_zh": "https://web.klokah.tw/text/sound/35729/556197.mp3"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_vocab_2d93c2d409bd', 'language/puyuma/audio/puyuma-audio-fba7d6ccb2ce', 'vocabulary', 'puyuma-audio-fba7d6ccb2ce', '我喜歡游泳，放假的時候，我們全家會一起去游泳。', '知本卑南語：sahar ku pakulimalima, nu katalaulepan i kungkuwan mu, salrangan mi saruma’enan mukuwa pakulimaya.', 'sahar ku pakulimalima, nu katalaulepan i kungkuwan mu, salrangan mi saruma’enan mukuwa pakulimaya. / 我喜歡游泳，放假的時候，我們全家會一起去游泳。 / I like swimming. During the holidays, our whole family go swimming together.', '["卑南語", "語詞庫", "音檔", "知本卑南語", "教室與學校", "sahar ku pakulimalima, nu katalaulepan i kungkuwan mu, salrangan mi saruma’enan mukuwa pakulimaya.", "我喜歡游泳，放假的時候，我們全家會一起去游泳。"]', '["formosanbank_epark"]', 'public', 'approved_for_public_learning_preview_subset', 'low', 400, '[{"heading": "族語", "body_zh": "sahar ku pakulimalima, nu katalaulepan i kungkuwan mu, salrangan mi saruma’enan mukuwa pakulimaya."}, {"heading": "中文", "body_zh": "我喜歡游泳，放假的時候，我們全家會一起去游泳。"}, {"heading": "音檔", "body_zh": "https://web.klokah.tw/text/sound/35729/556198.mp3"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_vocab_167e980c4f35', 'language/puyuma/audio/puyuma-audio-15e0e7223043', 'vocabulary', 'puyuma-audio-15e0e7223043', '我喜歡認識新朋友，我們可以一起唱歌和游泳。', '知本卑南語：sahar ku manadam kana vekal na ali’an, aruwa mi salrangan semenay zi mukuwa pakulimaya.', 'sahar ku manadam kana vekal na ali’an, aruwa mi salrangan semenay zi mukuwa pakulimaya. / 我喜歡認識新朋友，我們可以一起唱歌和游泳。 / I love meeting new people, we can sing and swim together.', '["卑南語", "語詞庫", "音檔", "知本卑南語", "教室與學校", "sahar ku manadam kana vekal na ali’an, aruwa mi salrangan semenay zi mukuwa pakulimaya.", "我喜歡認識新朋友，我們可以一起唱歌和游泳。"]', '["formosanbank_epark"]', 'public', 'approved_for_public_learning_preview_subset', 'low', 400, '[{"heading": "族語", "body_zh": "sahar ku manadam kana vekal na ali’an, aruwa mi salrangan semenay zi mukuwa pakulimaya."}, {"heading": "中文", "body_zh": "我喜歡認識新朋友，我們可以一起唱歌和游泳。"}, {"heading": "音檔", "body_zh": "https://web.klokah.tw/text/sound/35729/556199.mp3"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_vocab_ddc5bc9e2740', 'language/puyuma/audio/puyuma-audio-c4005834c802', 'vocabulary', 'puyuma-audio-c4005834c802', '我是卑南族的小孩。', '知本卑南語：a alrak ku za Pinuyumayan.', 'a alrak ku za Pinuyumayan. / 我是卑南族的小孩。 / I am an Pinuyumayan child.', '["卑南語", "語詞庫", "音檔", "知本卑南語", "教室與學校", "a alrak ku za Pinuyumayan.", "我是卑南族的小孩。"]', '["formosanbank_epark"]', 'public', 'approved_for_public_learning_preview_subset', 'low', 400, '[{"heading": "族語", "body_zh": "a alrak ku za Pinuyumayan."}, {"heading": "中文", "body_zh": "我是卑南族的小孩。"}, {"heading": "音檔", "body_zh": "https://web.klokah.tw/text/sound/35733/556243.mp3"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_vocab_42da2fe7cf7f', 'language/puyuma/audio/puyuma-audio-cb87557f60ad', 'vocabulary', 'puyuma-audio-cb87557f60ad', '我們家共有五個人。', '知本卑南語：lralruwatr mi saruma’enan.', 'lralruwatr mi saruma’enan. / 我們家共有五個人。 / There are five people in our family.', '["卑南語", "語詞庫", "音檔", "知本卑南語", "教室與學校", "lralruwatr mi saruma’enan.", "我們家共有五個人。"]', '["formosanbank_epark"]', 'public', 'approved_for_public_learning_preview_subset', 'low', 400, '[{"heading": "族語", "body_zh": "lralruwatr mi saruma’enan."}, {"heading": "中文", "body_zh": "我們家共有五個人。"}, {"heading": "音檔", "body_zh": "https://web.klokah.tw/text/sound/35733/556245.mp3"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_vocab_2c91f271ae76', 'language/puyuma/audio/puyuma-audio-96ee5840e608', 'vocabulary', 'puyuma-audio-96ee5840e608', '我們家有三個兄弟姊妹。', '知本卑南語：kaniyam saruma’enan tatelu mi maruwadiyadi.', 'kaniyam saruma’enan tatelu mi maruwadiyadi. / 我們家有三個兄弟姊妹。 / There are three brothers and sisters in our family.', '["卑南語", "語詞庫", "音檔", "知本卑南語", "教室與學校", "kaniyam saruma’enan tatelu mi maruwadiyadi.", "我們家有三個兄弟姊妹。"]', '["formosanbank_epark"]', 'public', 'approved_for_public_learning_preview_subset', 'low', 400, '[{"heading": "族語", "body_zh": "kaniyam saruma’enan tatelu mi maruwadiyadi."}, {"heading": "中文", "body_zh": "我們家有三個兄弟姊妹。"}, {"heading": "音檔", "body_zh": "https://web.klokah.tw/text/sound/35733/556246.mp3"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_vocab_5823efebac68', 'language/puyuma/audio/puyuma-audio-3e8e95834aec', 'vocabulary', 'puyuma-audio-3e8e95834aec', '我今天七點到學校。', '西群卑南語：meredek ku i takesiyan a pituwa tuki harem kana wari.', 'meredek ku i takesiyan a pituwa tuki harem kana wari. / 我今天七點到學校。 / I arrived at school at seven today.', '["卑南語", "語詞庫", "音檔", "西群卑南語", "教室與學校", "meredek ku i takesiyan a pituwa tuki harem kana wari.", "我今天七點到學校。"]', '["formosanbank_epark"]', 'public', 'approved_for_public_learning_preview_subset', 'low', 400, '[{"heading": "族語", "body_zh": "meredek ku i takesiyan a pituwa tuki harem kana wari."}, {"heading": "中文", "body_zh": "我今天七點到學校。"}, {"heading": "音檔", "body_zh": "https://web.klokah.tw/text/sound/35773/556886.mp3"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_vocab_f99e6a4c4d21', 'language/puyuma/audio/puyuma-audio-595e0d902d82', 'vocabulary', 'puyuma-audio-595e0d902d82', '上課的時候，老師教我們數字的族語。', '西群卑南語：a temakesi mi mu, tu panadamaw mi kana sinsi za aiyupan. kananta piningaiyan.', 'a temakesi mi mu, tu panadamaw mi kana sinsi za aiyupan. kananta piningaiyan. / 上課的時候，老師教我們數字的族語。 / In class, the teacher taught us the Pinuyumayan language of numbers.', '["卑南語", "語詞庫", "音檔", "西群卑南語", "教室與學校", "a temakesi mi mu, tu panadamaw mi kana sinsi za aiyupan. kananta piningaiyan.", "上課的時候，老師教我們數字的族語。"]', '["formosanbank_epark"]', 'public', 'approved_for_public_learning_preview_subset', 'low', 400, '[{"heading": "族語", "body_zh": "a temakesi mi mu, tu panadamaw mi kana sinsi za aiyupan. kananta piningaiyan."}, {"heading": "中文", "body_zh": "上課的時候，老師教我們數字的族語。"}, {"heading": "音檔", "body_zh": "https://web.klokah.tw/text/sound/35773/556889.mp3"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_vocab_e191d4ff4f15', 'language/puyuma/audio/puyuma-audio-f720172af555', 'vocabulary', 'puyuma-audio-f720172af555', '我們家住在初鹿部落。', '西群卑南語：ulra naniyam ruma’ i Mulivelivek.', 'ulra naniyam ruma’ i Mulivelivek. / 我們家住在初鹿部落。 / Our family lives in Mulivelivek.', '["卑南語", "語詞庫", "音檔", "西群卑南語", "教室與學校", "ulra naniyam ruma’ i Mulivelivek.", "我們家住在初鹿部落。"]', '["formosanbank_epark"]', 'public', 'approved_for_public_learning_preview_subset', 'low', 400, '[{"heading": "族語", "body_zh": "ulra naniyam ruma’ i Mulivelivek."}, {"heading": "中文", "body_zh": "我們家住在初鹿部落。"}, {"heading": "音檔", "body_zh": "https://web.klokah.tw/text/sound/35781/556993.mp3"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_vocab_916f1610103b', 'language/puyuma/audio/puyuma-audio-40cee4a7b4a2', 'vocabulary', 'puyuma-audio-40cee4a7b4a2', '上課了，老師走進教室，班長說:「起立!敬禮!」', '西群卑南語：kemiyarakaz lra temakesi, musavak na sinsi kana talrevaw, kema na pancang, “katikezir! sungal!”', 'kemiyarakaz lra temakesi, musavak na sinsi kana talrevaw, kema na pancang, “katikezir! sungal!” / 上課了，老師走進教室，班長說:「起立!敬禮!」 / It’s time for class, the teacher walked into the classroom, and the monitor said: “Stand up! Salute!”', '["卑南語", "語詞庫", "音檔", "西群卑南語", "教室與學校", "kemiyarakaz lra temakesi, musavak na sinsi kana talrevaw, kema na pancang, “katikezir! sungal!”", "上課了，老師走進教室，班長說:「起立!敬禮!」"]', '["formosanbank_epark"]', 'public', 'approved_for_public_learning_preview_subset', 'low', 400, '[{"heading": "族語", "body_zh": "kemiyarakaz lra temakesi, musavak na sinsi kana talrevaw, kema na pancang, “katikezir! sungal!”"}, {"heading": "中文", "body_zh": "上課了，老師走進教室，班長說:「起立!敬禮!」"}, {"heading": "音檔", "body_zh": "https://web.klokah.tw/text/sound/35773/556887.mp3"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_vocab_34da833569eb', 'language/puyuma/audio/puyuma-audio-f3b81e5909b4', 'vocabulary', 'puyuma-audio-f3b81e5909b4', '我們大聲的說:「老師好。」', '西群卑南語：kema’izang mi marengay, “’inavayan sinsi.”', 'kema’izang mi marengay, “’inavayan sinsi.” / 我們大聲的說:「老師好。」 / We said loudly, “Hi, teacher.”', '["卑南語", "語詞庫", "音檔", "西群卑南語", "問候語", "kema’izang mi marengay, “’inavayan sinsi.”", "我們大聲的說:「老師好。」"]', '["formosanbank_epark"]', 'public', 'approved_for_public_learning_preview_subset', 'low', 400, '[{"heading": "族語", "body_zh": "kema’izang mi marengay, “’inavayan sinsi.”"}, {"heading": "中文", "body_zh": "我們大聲的說:「老師好。」"}, {"heading": "音檔", "body_zh": "https://web.klokah.tw/text/sound/35773/556888.mp3"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_vocab_438c048cf59a', 'language/puyuma/audio/puyuma-audio-c1f05d8abee4', 'vocabulary', 'puyuma-audio-c1f05d8abee4', '我們跟著老師唸，我們唱了數字歌。', '西群卑南語：iturus mi kana sinsi miyup, zi semenay mi kana senay na aiyupan.', 'iturus mi kana sinsi miyup, zi semenay mi kana senay na aiyupan. / 我們跟著老師唸，我們唱了數字歌。 / We followed the teacher to read, we sang the number song.', '["卑南語", "語詞庫", "音檔", "西群卑南語", "教室與學校", "iturus mi kana sinsi miyup, zi semenay mi kana senay na aiyupan.", "我們跟著老師唸，我們唱了數字歌。"]', '["formosanbank_epark"]', 'public', 'approved_for_public_learning_preview_subset', 'low', 400, '[{"heading": "族語", "body_zh": "iturus mi kana sinsi miyup, zi semenay mi kana senay na aiyupan."}, {"heading": "中文", "body_zh": "我們跟著老師唸，我們唱了數字歌。"}, {"heading": "音檔", "body_zh": "https://web.klokah.tw/text/sound/35773/556890.mp3"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_vocab_7831e6e79850', 'language/puyuma/audio/puyuma-audio-c05c1fa52c34', 'vocabulary', 'puyuma-audio-c05c1fa52c34', '我學會好多族語。', '西群卑南語：sazu ku nilrazalrazam nanta piningaiyan.', 'sazu ku nilrazalrazam nanta piningaiyan. / 我學會好多族語。 / I have learned many Pinuyumayan languages.', '["卑南語", "語詞庫", "音檔", "西群卑南語", "教室與學校", "sazu ku nilrazalrazam nanta piningaiyan.", "我學會好多族語。"]', '["formosanbank_epark"]', 'public', 'approved_for_public_learning_preview_subset', 'low', 400, '[{"heading": "族語", "body_zh": "sazu ku nilrazalrazam nanta piningaiyan."}, {"heading": "中文", "body_zh": "我學會好多族語。"}, {"heading": "音檔", "body_zh": "https://web.klokah.tw/text/sound/35773/556891.mp3"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_vocab_ef0969b17022', 'language/puyuma/audio/puyuma-audio-977400f1160f', 'vocabulary', 'puyuma-audio-977400f1160f', '我天天上學，我天天學族語，我要講給媽媽聽。', '西群卑南語：kana wariwari mukuwa ku i takesiyan, kana wariwari menadanadam ku kanata piningaiyan, rarengay ku pakinger kani inani.', 'kana wariwari mukuwa ku i takesiyan, kana wariwari menadanadam ku kanata piningaiyan, rarengay ku pakinger kani inani. / 我天天上學，我天天學族語，我要講給媽媽聽。 / I go to school every day, I learn the Pinuyumayan language every day, and I want to tell my mother.', '["卑南語", "語詞庫", "音檔", "西群卑南語", "教室與學校", "kana wariwari mukuwa ku i takesiyan, kana wariwari menadanadam ku kanata piningaiyan, rarengay ku pakinger kani inani.", "我天天上學，我天天學族語，我要講給媽媽聽。"]', '["formosanbank_epark"]', 'public', 'approved_for_public_learning_preview_subset', 'low', 400, '[{"heading": "族語", "body_zh": "kana wariwari mukuwa ku i takesiyan, kana wariwari menadanadam ku kanata piningaiyan, rarengay ku pakinger kani inani."}, {"heading": "中文", "body_zh": "我天天上學，我天天學族語，我要講給媽媽聽。"}, {"heading": "音檔", "body_zh": "https://web.klokah.tw/text/sound/35773/556892.mp3"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_vocab_aef2f8c84b4b', 'language/puyuma/audio/puyuma-audio-6b36c9270538', 'vocabulary', 'puyuma-audio-6b36c9270538', '我的名字是Inor。', '西群卑南語：i Inor nanku ngadan.', 'i Inor nanku ngadan. / 我的名字是Inor。 / My name is Inor.', '["卑南語", "語詞庫", "音檔", "西群卑南語", "教室與學校", "i Inor nanku ngadan.", "我的名字是Inor。"]', '["formosanbank_epark"]', 'public', 'approved_for_public_learning_preview_subset', 'low', 400, '[{"heading": "族語", "body_zh": "i Inor nanku ngadan."}, {"heading": "中文", "body_zh": "我的名字是Inor。"}, {"heading": "音檔", "body_zh": "https://web.klokah.tw/text/sound/35777/556940.mp3"}]');
