INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_vocab_df50dfe6f264', 'language/puyuma/audio/puyuma-audio-352af7943610', 'vocabulary', 'puyuma-audio-352af7943610', '我有一個哥哥，他叫Singkay，他今年11歲。', '西群卑南語：ulra i ivalri, i Singkay nantu ngadan, muketrep misama’ za saya nantu ’ami harem.', 'ulra i ivalri, i Singkay nantu ngadan, muketrep misama’ za saya nantu ’ami harem. / 我有一個哥哥，他叫Singkay，他今年11歲。 / I have a brother, his name is Singkay, he is 11 years old.', '["卑南語", "語詞庫", "音檔", "西群卑南語", "教室與學校", "ulra i ivalri, i Singkay nantu ngadan, muketrep misama’ za saya nantu ’ami harem.", "我有一個哥哥，他叫Singkay，他今年11歲。"]', '["formosanbank_epark"]', 'public', 'approved_for_public_learning_preview_subset', 'low', 400, '[{"heading": "族語", "body_zh": "ulra i ivalri, i Singkay nantu ngadan, muketrep misama’ za saya nantu ’ami harem."}, {"heading": "中文", "body_zh": "我有一個哥哥，他叫Singkay，他今年11歲。"}, {"heading": "音檔", "body_zh": "https://web.klokah.tw/text/sound/35777/556944.mp3"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_vocab_1a4adc7401a1', 'language/puyuma/audio/puyuma-audio-7fbfd8c8045d', 'vocabulary', 'puyuma-audio-7fbfd8c8045d', '我們在同一間學校讀書。', '西群卑南語：mukasa mi temakesi kana maresan na takesiyan.', 'mukasa mi temakesi kana maresan na takesiyan. / 我們在同一間學校讀書。 / We study in the same school.', '["卑南語", "語詞庫", "音檔", "西群卑南語", "教室與學校", "mukasa mi temakesi kana maresan na takesiyan.", "我們在同一間學校讀書。"]', '["formosanbank_epark"]', 'public', 'approved_for_public_learning_preview_subset', 'low', 400, '[{"heading": "族語", "body_zh": "mukasa mi temakesi kana maresan na takesiyan."}, {"heading": "中文", "body_zh": "我們在同一間學校讀書。"}, {"heading": "音檔", "body_zh": "https://web.klokah.tw/text/sound/35777/556945.mp3"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_vocab_eb7cdce1af97', 'language/puyuma/audio/puyuma-audio-0aa5dc53e189', 'vocabulary', 'puyuma-audio-0aa5dc53e189', '我和哥哥都喜歡唱歌。', '西群卑南語：sahar mi semenay iniyam i ivalri na ma’inayan.', 'sahar mi semenay iniyam i ivalri na ma’inayan. / 我和哥哥都喜歡唱歌。 / Both my brother and I like to sing.', '["卑南語", "語詞庫", "音檔", "西群卑南語", "教室與學校", "sahar mi semenay iniyam i ivalri na ma’inayan.", "我和哥哥都喜歡唱歌。"]', '["formosanbank_epark"]', 'public', 'approved_for_public_learning_preview_subset', 'low', 400, '[{"heading": "族語", "body_zh": "sahar mi semenay iniyam i ivalri na ma’inayan."}, {"heading": "中文", "body_zh": "我和哥哥都喜歡唱歌。"}, {"heading": "音檔", "body_zh": "https://web.klokah.tw/text/sound/35777/556946.mp3"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_vocab_19a0b8cc7269', 'language/puyuma/audio/puyuma-audio-75abd617e2fb', 'vocabulary', 'puyuma-audio-75abd617e2fb', '我喜歡游泳，放假的時候，我們全家會一起去游泳。', '西群卑南語：sahar ku melrangulranguya nu katalaulepan, marelrang mi saruma’enan mukuwa melrangulranguya.', 'sahar ku melrangulranguya nu katalaulepan, marelrang mi saruma’enan mukuwa melrangulranguya. / 我喜歡游泳，放假的時候，我們全家會一起去游泳。 / I like swimming. During the holidays, our whole family go swimming together.', '["卑南語", "語詞庫", "音檔", "西群卑南語", "教室與學校", "sahar ku melrangulranguya nu katalaulepan, marelrang mi saruma’enan mukuwa melrangulranguya.", "我喜歡游泳，放假的時候，我們全家會一起去游泳。"]', '["formosanbank_epark"]', 'public', 'approved_for_public_learning_preview_subset', 'low', 400, '[{"heading": "族語", "body_zh": "sahar ku melrangulranguya nu katalaulepan, marelrang mi saruma’enan mukuwa melrangulranguya."}, {"heading": "中文", "body_zh": "我喜歡游泳，放假的時候，我們全家會一起去游泳。"}, {"heading": "音檔", "body_zh": "https://web.klokah.tw/text/sound/35777/556947.mp3"}]');
INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_vocab_e9dec98a7c3e', 'language/puyuma/audio/puyuma-audio-9f9593e40ba5', 'vocabulary', 'puyuma-audio-9f9593e40ba5', '我喜歡認識新朋友，我們可以一起唱歌和游泳。', '西群卑南語：sahar ku malrazam za vekal za ’ali’an, karuwa mi mukasa semenasenay zi melrangulranguy.', 'sahar ku malrazam za vekal za ’ali’an, karuwa mi mukasa semenasenay zi melrangulranguy. / 我喜歡認識新朋友，我們可以一起唱歌和游泳。 / I love meeting new people, we can sing and swim together.', '["卑南語", "語詞庫", "音檔", "西群卑南語", "教室與學校", "sahar ku malrazam za vekal za ’ali’an, karuwa mi mukasa semenasenay zi melrangulranguy.", "我喜歡認識新朋友，我們可以一起唱歌和游泳。"]', '["formosanbank_epark"]', 'public', 'approved_for_public_learning_preview_subset', 'low', 400, '[{"heading": "族語", "body_zh": "sahar ku malrazam za vekal za ’ali’an, karuwa mi mukasa semenasenay zi melrangulranguy."}, {"heading": "中文", "body_zh": "我喜歡認識新朋友，我們可以一起唱歌和游泳。"}, {"heading": "音檔", "body_zh": "https://web.klokah.tw/text/sound/35777/556948.mp3"}]');
