INSERT INTO public_knowledge_cards_v16 (id, slug, entity_type, entity_id, title_zh, summary_zh, body_zh, keywords_json, source_ids_json, release_channel, review_status, sensitivity, sort_order, sections_json) VALUES ('card_vocab_bc1d0ec3ce44', 'language/puyuma/audio/puyuma-audio-7701493ee98e', 'vocabulary', 'puyuma-audio-7701493ee98e', '我母親是都歷的阿美族，我父親是南王人。', '建和卑南語：i nani mu Amis i Tulik, i malri mu Puyuma.', 'i nani mu Amis i Tulik, i malri mu Puyuma. / 我母親是都歷的阿美族，我父親是南王人。', '["卑南語", "語詞庫", "音檔", "建和卑南語", "家庭與部落", "i nani mu Amis i Tulik, i malri mu Puyuma.", "我母親是都歷的阿美族，我父親是南王人。"]', '["formosanbank_epark"]', 'public', 'approved_for_public_learning_preview_subset', 'low', 400, '[{"heading": "族語", "body_zh": "i nani mu Amis i Tulik, i malri mu Puyuma."}, {"heading": "中文", "body_zh": "我母親是都歷的阿美族，我父親是南王人。"}, {"heading": "音檔", "body_zh": "https://klokah.tw/extension/con_data/sound/41/sentence/41c2s10.mp3"}]');
