INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_4bb85c72ef9b', 'community', 'puyuma', 'communities/puyuma', '南王部落資料卡', '南王是卑南族重要核心部落之一；平台中 Puyuma 僅指南王部落或英文語境中的卑南語，不可用來代稱整個卑南族。；羅馬拼音：Puyuma；來源系統：竹生系統；行政提示：臺東市南王里', '["Nanwang", "Puyuma", "十社", "卑南族", "卑南社", "南王", "南王部落", "大獵祭", "少年年祭", "巫師祭", "年祭", "普悠瑪部落", "海祭/小米收穫祭", "音樂人才"]', 'public', '["cip_puyuma_profile"]', 100, '2026-06-11T14:20:00+08:00');
INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_9e4c8bada6c2', 'community', 'katratripulr', 'communities/katratripulr', '知本部落資料卡', '知本是石生系統的重要核心，與建和等部落在起源敘事與四月祭祖脈絡中常被並讀。；羅馬拼音：Katratripulr；來源系統：石生系統；行政提示：臺東市知本里', '["Katipul", "Katratipul", "Katratripulr", "Katripul", "Zhiben", "十社", "卑南族", "卡大地布", "收穫祭", "會所復振", "知本", "知本卑南語", "石生起源", "祖先登陸與發祥地祭祖"]', 'public', '["cip_puyuma_profile", "formosanbank_dialects_csv"]', 100, '2026-06-11T14:20:00+08:00');
INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_3ce8b0ced423', 'community', 'kasavakan', 'communities/kasavakan', '建和部落資料卡', '建和以祭祖、收穫祭與年祭脈絡重要；語料上對應 FormosanBank Jianhe_Puyuma。；羅馬拼音：Kasavakan；來源系統：石生系統；行政提示：臺東市建和里', '["Jianhe", "Kasavakan", "Samagan", "十社", "卑南族", "射馬干", "小米收穫祭", "巨型鞦韆", "年祭", "建和", "建和卑南語", "建和部落", "祖先登陸與發祥地祭祖"]', 'public', '["cip_puyuma_profile", "formosanbank_dialects_csv"]', 100, '2026-06-11T14:20:00+08:00');
