INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_1c49f0042b13', 'ritual', 'millet_harvest_rite', 'rituals/millet_harvest_rite', '小米收穫祭', '以家族與部落為單位感謝收穫，與小米、祭司、婦女角色、祈福及部落活動相關。；時間提示：國曆7月；部落可能為3至7天不等；類別：農事祭儀', '["卑南族", "國曆7月；部落可能為3至7天不等", "家族", "小米", "小米收穫祭", "感恩", "收穫", "祈福", "祭儀", "農事祭儀"]', 'public', '["cip_puyuma_profile"]', 90, '2026-06-11T14:20:00+08:00');
INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_db14c4f781c6', 'ritual', 'annual_festival', 'rituals/annual_festival', '年祭', '卑南族最重要的年度活動之一，常包含少年年祭、大獵祭、慶功、除喪與部落團聚。；時間提示：國曆12月；部分部落延續至跨年脈絡；類別：歲時祭儀/生命禮俗', '["卑南族", "國曆12月；部分部落延續至跨年脈絡", "年祭", "會所", "歲時祭儀/生命禮俗", "祭儀", "花環", "部落團聚", "除喪"]', 'public', '["cip_puyuma_profile"]', 90, '2026-06-11T14:20:00+08:00');
INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_672792f9b5f5', 'ritual', 'mangamangayaw_youth_rite', 'rituals/mangamangayaw_youth_rite', '少年年祭', '與少年膽識、會所訓練及成年過程相關；現代公開活動多以象徵方式延續，不使用真猴。；時間提示：多在12月下旬；依部落公告；類別：年齡階級/少年訓練', '["卑南族", "多在12月下旬；依部落公告", "少年", "少年年祭", "年齡階級/少年訓練", "文化教育", "會所", "祭儀", "膽識"]', 'public', '["cip_puyuma_profile"]', 90, '2026-06-11T14:20:00+08:00');
INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_188fe68a3190', 'ritual', 'mangayaw_great_hunting_rite', 'rituals/mangayaw_great_hunting_rite', '大獵祭', '與男子成年、野外求生、狩獵訓練、凱旋迎接與部落慰問相關，是年祭核心內容之一。；時間提示：國曆12月下旬；部落可能不同；類別：成年/狩獵/年祭', '["凱旋門", "卑南族", "國曆12月下旬；部落可能不同", "大獵祭", "成年", "成年/狩獵/年祭", "狩獵", "祭儀", "野外求生"]', 'public', '["cip_puyuma_profile"]', 90, '2026-06-11T14:20:00+08:00');
INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_5c689d52e5ea', 'ritual', 'united_annual_festival', 'rituals/united_annual_festival', '聯合年祭', '由各部落輪流或共同辦理，以歌舞、競賽與交流凝聚卑南族共同體意識。；時間提示：時間不定；由部落聯合會議或主辦單位公告；類別：跨部落交流', '["交流", "十社", "卑南族", "族群凝聚", "時間不定；由部落聯合會議或主辦單位公告", "歌舞", "祭儀", "聯合年祭", "跨部落交流"]', 'public', '["cip_puyuma_profile"]', 90, '2026-06-11T14:20:00+08:00');
INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_6ede49aeb9d6', 'fact', 'profile_plain_crossroads', 'facts/profile_plain_crossroads', '族群簡介', '卑南族位於多族群交會的平原地帶，長期與外界文化接觸，同時仍維繫傳統文化與生活。', '["卑南族", "族群簡介"]', 'public', '["cip_puyuma_profile"]', 60, '2026-06-11T14:20:00+08:00');
INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_7c41f8996d86', 'fact', 'profile_age_house_core', 'facts/profile_age_house_core', '社會制度', '卑南族社會以嚴謹的年齡階級組織與會所制度聞名，這兩者是理解部落公共生活的重要基礎。', '["卑南族", "社會制度"]', 'preview', '["cip_puyuma_profile"]', 60, '2026-06-11T14:20:00+08:00');
INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_8619269cdcac', 'fact', 'profile_annual_rituals_overview', 'facts/profile_annual_rituals_overview', '祭儀', '卑南族現今仍有小米除草完工、小米收穫、少年年祭、年祭與大獵祭等年度慶典，其中年祭規模最大。', '["卑南族", "祭儀"]', 'preview', '["cip_puyuma_profile"]', 60, '2026-06-11T14:20:00+08:00');
INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_7cd569763eb6', 'fact', 'name_puyuma_pinuyumayan_distinction', 'facts/name_puyuma_pinuyumayan_distinction', '正名', 'Puyuma 源自南王部落名稱；為避免族稱與部落名混用，近年有族人提倡以 Pinuyumayan 作為卑南族族稱。', '["卑南族", "正名"]', 'public', '["cip_puyuma_profile"]', 60, '2026-06-11T14:20:00+08:00');
INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_0265e4b19086', 'fact', 'origin_bamboo_stone', 'facts/origin_bamboo_stone', '起源敘事', '卑南族起源敘事常見「竹生」與「石生」兩大說法，前者以卑南社/南王為中心，後者以知本社為中心。', '["卑南族", "起源敘事"]', 'preview', '["cip_puyuma_profile"]', 60, '2026-06-11T14:20:00+08:00');
INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_ef11e1f52e8a', 'fact', 'settlement_core_area', 'facts/settlement_core_area', '部落地理', '現代卑南族主要以臺東平原的臺東市、卑南鄉一帶為核心，也有族人居住成功鎮、太麻里鄉或移居都市。', '["卑南族", "部落地理"]', 'public', '["cip_puyuma_profile"]', 60, '2026-06-11T14:20:00+08:00');
INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_cb3a81d2dd94', 'fact', 'community_list_public', 'facts/community_list_public', '部落地理', '公開資料列出知本、建和、南王、寶桑、利嘉、泰安、上賓朗、下賓朗、初鹿、龍過脈等卑南族主要部落脈絡。', '["卑南族", "部落地理"]', 'public', '["cip_puyuma_profile"]', 60, '2026-06-11T14:20:00+08:00');
INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_a9da640785c8', 'fact', 'agriculture_millet_to_rice', 'facts/agriculture_millet_to_rice', '產業', '卑南族早期農作以小米為重要作物，後來也有禾、麻、菽、麥等作物；水稻耕作技術在歷史敘事中與卑南王 Pinadray 有關。', '["卑南族", "產業"]', 'public', '["cip_puyuma_profile"]', 60, '2026-06-11T14:20:00+08:00');
INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_818fe6305a2b', 'fact', 'modern_economic_crops', 'facts/modern_economic_crops', '產業', '1960年代以後，部分卑南族地區的作物轉向釋迦、荖葉等經濟作物。', '["卑南族", "產業"]', 'public', '["cip_puyuma_profile"]', 60, '2026-06-11T14:20:00+08:00');
INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_2548293b218c', 'fact', 'traditional_food_staples', 'facts/traditional_food_staples', '飲食', '卑南族傳統飲食包含粟、旱稻、甘薯、芋頭，以及狩獵、河川魚貝取得的蛋白質來源。', '["卑南族", "飲食"]', 'public', '["cip_puyuma_profile"]', 60, '2026-06-11T14:20:00+08:00');
INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_4cbf67e80a4f', 'fact', 'festival_food_shell_ginger', 'facts/festival_food_shell_ginger', '飲食', '月桃葉包裹的糯米粉糰、鹹豬肉做成的月桃小米或糯米粿粽，是公開介紹中常見的卑南族慶典食物代表。', '["卑南族", "飲食"]', 'public', '["cip_puyuma_profile"]', 60, '2026-06-11T14:20:00+08:00');
