INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_3a5321e37a25', 'fact', 'dance_role_difference', 'facts/dance_role_difference', '舞蹈', '卑南族舞蹈反映男女與年齡角色差異，跳舞時需遵守個人社會身分所對應的舞步。', '["卑南族", "舞蹈"]', 'preview', '["cip_puyuma_profile"]', 60, '2026-06-11T14:20:00+08:00');
INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_b1ea3831f534', 'fact', 'shield_dance_spiritual_step', 'facts/shield_dance_spiritual_step', '舞蹈', '公開介紹提及猴祭時的舞步、勇士持盾牌的舞步，以及具感恩、賜福、守護部落意義的精神舞步。', '["卑南族", "舞蹈"]', 'preview', '["cip_puyuma_profile"]', 60, '2026-06-11T14:20:00+08:00');
INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_b9f6cb0480a9', 'fact', 'language_regional_variation', 'facts/language_regional_variation', '族語', '卑南語因部落區位與族群接觸經驗而有差異，例如知本受排灣族、魯凱族語影響，北部卑南部落受阿美族語發音方式影響。', '["卑南族", "族語"]', 'public', '["cip_puyuma_profile"]', 60, '2026-06-11T14:20:00+08:00');
INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_f998585b93d8', 'fact', 'kinship_matrilineal_summary', 'facts/kinship_matrilineal_summary', '親屬制度', '卑南族傳統婚姻家庭以母系大家族制為原則，重視母系家系、本家與宗家觀念；現代運作已有變化。', '["卑南族", "親屬制度"]', 'preview', '["cip_puyuma_profile"]', 60, '2026-06-11T14:20:00+08:00');
INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_9e1c33c3ebc7', 'fact', 'kinship_inheritance_marriage', 'facts/kinship_inheritance_marriage', '親屬制度', '公開介紹指出傳統上家族氏名與家屋財產由長女繼承，居住方式以男子入居女方家庭為原則，但現代從妻居已相當少見。', '["卑南族", "親屬制度"]', 'preview', '["cip_puyuma_profile"]', 60, '2026-06-11T14:20:00+08:00');
INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_68d21aceb73b', 'fact', 'leadership_ayawan_rahan', 'facts/leadership_ayawan_rahan', '部落制度', '卑南族傳統部落政治領袖 ayawan 負責重大事件協調；祭司 rahan 掌管祭祀禮儀並需熟知曆法、氣象、歷史、歌謠與舞蹈。', '["卑南族", "部落制度"]', 'preview', '["cip_puyuma_profile"]', 60, '2026-06-11T14:20:00+08:00');
INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_1006293cea24', 'fact', 'shaman_role_public_summary', 'facts/shaman_role_public_summary', '信仰/巫師', '公開介紹指出巫師 na temaramaw 可為男女，與祈福、治病、驅邪等照護需求相關；平台僅可公開摘要，不得產生作法教學。', '["信仰/巫師", "卑南族"]', 'preview', '["cip_puyuma_profile"]', 60, '2026-06-11T14:20:00+08:00');
INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_a1d89f749162', 'fact', 'age_grade_training_stages', 'facts/age_grade_training_stages', '年齡階級', '公開介紹指出少年約12、13歲進入少年會所，17、18歲轉入成年會所；訓練包含體能、知識、競走、摔角、野外求生與狩獵等。', '["卑南族", "年齡階級"]', 'preview', '["cip_puyuma_profile"]', 60, '2026-06-11T14:20:00+08:00');
INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_4c475edbe580', 'fact', 'revitalization_1991', 'facts/revitalization_1991', '文化復振', '公開介紹指出1991年前後，知本、初鹿與南王等部落建新會所、成立青年會或文化工作協會，推動尋根與母語復振。', '["卑南族", "文化復振"]', 'public', '["cip_puyuma_profile"]', 60, '2026-06-11T14:20:00+08:00');
INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_ff0eec6fc24f', 'fact', 'spiritual_biruwa', 'facts/spiritual_biruwa', '傳統信仰', '卑南族傳統信仰認為自然、天地、四方、祖先與死者之靈等皆存在，神靈稱為 biruwa。', '["傳統信仰", "卑南族"]', 'preview', '["cip_puyuma_profile"]', 60, '2026-06-11T14:20:00+08:00');
INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_21a2eaf5aeca', 'fact', 'divination_public_summary', 'facts/divination_public_summary', '傳統信仰', '公開介紹提到卑南族巫術中有占卜行為，並以夢兆與鳥占為主；此內容僅適合摘要，不可操作化。', '["傳統信仰", "卑南族"]', 'preview', '["cip_puyuma_profile"]', 60, '2026-06-11T14:20:00+08:00');
