INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_abad693b8b53', 'fact', 'millet_harvest_public', 'facts/millet_harvest_public', '祭儀', '小米收穫祭以家族為單位，公開介紹提及3至7天活動、祭司夢占與驅邪、婦女小米田祭品及收割儀式等；平台不公開操作步驟。', '["卑南族", "祭儀"]', 'preview', '["cip_puyuma_profile"]', 60, '2026-06-11T14:20:00+08:00');
