INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_a63b8cdae350', 'fact', 'joint_annual_festival_1982', 'facts/joint_annual_festival_1982', '聯合年祭', '公開介紹指出卑南族各部落自1982年起逐漸發展出聯合年祭，由部落輪流舉辦，成為部落交誼與凝聚民族意識的重要活動。', '["卑南族", "聯合年祭"]', 'preview', '["cip_puyuma_profile"]', 60, '2026-06-11T14:20:00+08:00');
INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_3f7bbc112454', 'fact', 'formosanbank_epark_structure', 'facts/formosanbank_epark_structure', '族語語料', 'FormosanBank 的 ePark 資料包含 ePark_1、ePark_2、ePark_3 等來源資料，並整理為 FormosanBank XML 格式，可作族語教材與音檔索引依據。', '["卑南族", "族語語料"]', 'public', '["formosanbank_epark_readme"]', 60, '2026-06-11T14:20:00+08:00');
