INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_cb8f634d5aa1', 'fact', 'history_japanese_classification_pinuyumayan', 'facts/history_japanese_classification_pinuyumayan', '歷史分類', '公開資料指出，十九世紀末進入日本殖民統治時期後，卑南族在民族文化分類上被稱為 Pinuyumayan，並因主要有八個部落而被稱為「八社蕃」；平台只能將「八社」作歷史用語，不可作正式分類。', '["卑南族", "歷史分類"]', 'preview', '["cip_puyuma_profile"]', 60, '2026-06-11T14:20:00+08:00');
INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_1b69d8e838df', 'fact', 'migration_hengchun_sukaro_public', 'facts/migration_hengchun_sukaro_public', '歷史遷徙', '公開資料指出，十八世紀有一部分卑南族氏族遷居恆春半島並發展出稱為「斯卡羅」（sukaro）的歷史脈絡；此主題涉及跨族群歷史，平台應以來源摘要呈現並標記待專題審核。', '["卑南族", "歷史遷徙"]', 'preview', '["cip_puyuma_profile"]', 60, '2026-06-11T14:20:00+08:00');
INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_dc8da3e08510', 'fact', 'urban_migration_modern_fields', 'facts/urban_migration_modern_fields', '現代發展', '公開資料指出，目前有不少卑南族人離開東部到都市發展，並活躍於各領域；平台可建立「都會族人與現代發展」內容分類，但人物條目需另行來源查證。', '["卑南族", "現代發展"]', 'public', '["cip_puyuma_profile"]', 60, '2026-06-11T14:20:00+08:00');
INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_c578b98326ed', 'fact', 'rice_technology_pinadray_public', 'facts/rice_technology_pinadray_public', '產業/歷史', '公開資料將十八世紀水稻耕作技術與器物的引進，連結到卑南王 Pinadray 的歷史敘事；此類歷史人物敘事應標示來源並避免過度擴寫。', '["卑南族", "產業/歷史"]', 'preview', '["cip_puyuma_profile"]', 60, '2026-06-11T14:20:00+08:00');
INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_0c87a59242c9', 'fact', 'male_clothing_parts_public', 'facts/male_clothing_parts_public', '服飾', '公開資料列出男子盛裝可包含上衣、黑短褲、套褲、檳榔袋、腰袋等，盛裝時也可佩刀並配戴琉璃珠或銀飾；平台應以服飾知識卡呈現，不替代部落穿著規範。', '["卑南族", "服飾"]', 'public', '["cip_puyuma_profile"]', 60, '2026-06-11T14:20:00+08:00');
