INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_b1d44bc85d46', 'fact', 'leader_priest_shaman_clothing_public', 'facts/leader_priest_shaman_clothing_public', '服飾/身分', '公開資料指出傳統領袖與祭師盛裝另有羽冠與肩袋，女靈媒或巫師另有肩飾；平台可作摘要，但不得產生身分判定或儀式穿著教學。', '["卑南族", "服飾/身分"]', 'preview', '["cip_puyuma_profile"]', 60, '2026-06-11T14:20:00+08:00');
