INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_e541139a1abb', 'fact', 'house_status_scale_public', 'facts/house_status_scale_public', '建築/社會身分', '公開資料提到傳統家屋規模大小與屋主社會地位相關，部落領導人直系家族家屋較大，旁系血親與一般家屋較小；平台應避免將此用於現代個人身分判斷。', '["卑南族", "建築/社會身分"]', 'preview', '["cip_puyuma_profile"]', 60, '2026-06-11T14:20:00+08:00');
INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_dbef2986a564', 'fact', 'musical_categories_detail_public', 'facts/musical_categories_detail_public', '音樂歌謠', '公開資料將卑南族歌謠分為祭儀歌謠、休閒工作歌謠與社會時代歌謠，並舉例猴祭、大獵祭、年祭歌謠以及婦女工作團工作歌等。', '["卑南族", "音樂歌謠"]', 'preview', '["cip_puyuma_profile"]', 60, '2026-06-11T14:20:00+08:00');
INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_42cf69563291', 'fact', 'dance_social_steps_rule', 'facts/dance_social_steps_rule', '舞蹈/社會角色', '公開資料指出卑南族舞蹈需依男女與年齡角色遵守相應舞步；平台展示舞蹈時應標示角色脈絡，避免把儀式舞步做成娛樂化教學。', '["卑南族", "舞蹈/社會角色"]', 'preview', '["cip_puyuma_profile"]', 60, '2026-06-11T14:20:00+08:00');
INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_838f042fab0e', 'fact', 'language_contact_north_south_public', 'facts/language_contact_north_south_public', '族語/方言差異', '公開資料指出卑南語因部落區位與族群接觸不同而有差異，例如南面知本部落受排灣族、魯凱族語影響，北面卑南部落受阿美族語發音方式影響。', '["卑南族", "族語/方言差異"]', 'public', '["cip_puyuma_profile"]', 60, '2026-06-11T14:20:00+08:00');
INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_6b048595b6f3', 'fact', 'kinship_clan_house_categories_public', 'facts/kinship_clan_house_categories_public', '親屬制度', '公開資料描述卑南族宗族與家屋觀念中，有大宗本家、小宗本家與分家等分類；平台僅可做制度摘要，不應收集或推測現代家族譜系。', '["卑南族", "親屬制度"]', 'preview', '["cip_puyuma_profile"]', 60, '2026-06-11T14:20:00+08:00');
INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_ee7a6e815279', 'fact', 'zhiben_three_clans_public_note', 'facts/zhiben_three_clans_public_note', '親屬制度/部落差異', '公開資料以知本社為例，提到三個氏族、共同祖廟、親族首長與會所等脈絡；此內容涉及部落內部制度，平台只做來源摘要並標記需部落審核。', '["卑南族", "親屬制度/部落差異"]', 'preview', '["cip_puyuma_profile"]', 60, '2026-06-11T14:20:00+08:00');
INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_efa007a9931b', 'fact', 'rahan_required_knowledge_public', 'facts/rahan_required_knowledge_public', '祭司/知識角色', '公開資料指出祭司 rahan 掌管祭祀禮儀，需熟知曆法、氣象、歷史、傳統歌謠與舞蹈；平台可列為角色摘要，不可產生祭儀主持教學。', '["卑南族", "祭司/知識角色"]', 'preview', '["cip_puyuma_profile"]', 60, '2026-06-11T14:20:00+08:00');
INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_8dec231285a1', 'fact', 'age_grade_adult_house_levels_public', 'facts/age_grade_adult_house_levels_public', '年齡階級', '公開資料指出進入成年會所後可分四到五個階級，成員須服從資深長者、負擔較多勞務並學習競走、摔角、野外求生與狩獵等技能。', '["卑南族", "年齡階級"]', 'preview', '["cip_puyuma_profile"]', 60, '2026-06-11T14:20:00+08:00');
INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_94575301057f', 'fact', 'modern_religion_coexistence_public', 'facts/modern_religion_coexistence_public', '宗教信仰/現代變遷', '公開資料指出卑南族除傳統信仰外，也有漢族信仰與西方基督宗教並存於現代生活；平台敘述現代宗教時應避免將單一信仰視為全部族人的共同狀態。', '["卑南族", "宗教信仰/現代變遷"]', 'preview', '["cip_puyuma_profile"]', 60, '2026-06-11T14:20:00+08:00');
INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_2a7289c6751d', 'fact', 'traditional_religion_revitalization_1981_public', 'facts/traditional_religion_revitalization_1981_public', '信仰/文化復振', '公開資料指出1981年後因傳統祭典恢復與振興，傳統宗教信仰觀念再度受到重視與討論；平台可作為文化復振時間線節點。', '["信仰/文化復振", "卑南族"]', 'preview', '["cip_puyuma_profile"]', 60, '2026-06-11T14:20:00+08:00');
INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_40035ceb680a', 'fact', 'millet_harvest_swing_public_rule', 'facts/millet_harvest_swing_public_rule', '祭儀/公開活動', '公開資料提到部分部落在小米收穫祭時於會所廣場搭鞦韆架，並賦予為農作祈福的象徵意義；平台可作文化活動介紹，但不替代部落祭儀說明。', '["卑南族", "祭儀/公開活動"]', 'preview', '["cip_puyuma_profile"]', 60, '2026-06-11T14:20:00+08:00');
INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_7e86784d4e2e', 'fact', 'annual_festival_preparation_public', 'facts/annual_festival_preparation_public', '年祭/準備工作', '公開資料指出年祭前族人會編織花環、準備食物與釀酒，部落周圍也會設立路障並整修會所、設立祭壇與刺猴祭壇；平台需避免公開禁忌或操作細節。', '["卑南族", "年祭/準備工作"]', 'preview', '["cip_puyuma_profile"]', 60, '2026-06-11T14:20:00+08:00');
INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_d66747dde5fc', 'fact', 'monkey_rite_exorcism_public', 'facts/monkey_rite_exorcism_public', '少年年祭/猴祭', '公開資料指出傳統猴祭前一晚，青少年有赤裸上身、塗炭灰、持芭蕉葉到各戶驅除邪魔的脈絡；平台只可摘要，不可做成仿作或教學內容。', '["卑南族", "少年年祭/猴祭"]', 'preview', '["cip_puyuma_profile"]', 60, '2026-06-11T14:20:00+08:00');
INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_2ae54a353129', 'fact', 'hunting_rite_return_ceremony_public', 'facts/hunting_rite_return_ceremony_public', '大獵祭', '公開資料指出大獵祭活動結束時，部落婦女會於部落外以竹子搭建凱旋門等待，男子回部落後由婦女更換禮服並共同慶功與慰問喪家。', '["卑南族", "大獵祭"]', 'preview', '["cip_puyuma_profile"]', 60, '2026-06-11T14:20:00+08:00');
INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_ca516336b852', 'fact', 'joint_festival_decision_body_public', 'facts/joint_festival_decision_body_public', '聯合年祭', '公開資料指出聯合年祭舉辦時間不定，由部落聯合會議決定，並由卑南族各部落輪流舉辦；平台不得自行公告日期，應連結部落或官方公告。', '["卑南族", "聯合年祭"]', 'public', '["cip_puyuma_profile"]', 60, '2026-06-11T14:20:00+08:00');
INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_d6b9d977e3c4', 'fact', 'formosanbank_epark_audio_failed_handling', 'facts/formosanbank_epark_audio_failed_handling', '族語語料/音檔治理', 'FormosanBank ePark README 說明有 failed_audio.csv 與 update_audio.py，用於記錄與移除下載失敗音檔相關標籤；平台建立語音 manifest 時應保留 failed/skipped 狀態，不可假設所有音檔都有效。', '["卑南族", "族語語料/音檔治理"]', 'public', '["formosanbank_epark_readme"]', 60, '2026-06-11T14:20:00+08:00');
INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_11bc7b3ccee3', 'fact', 'formosanbank_puyuma_orthography_note', 'facts/formosanbank_puyuma_orthography_note', '族語語料/正字法', 'FormosanBank ePark README 指出九階教材的 Puyuma 使用 Ortho94 轉換表，其他多數 Puyuma 子語料常見 Ortho113；平台匯入族語資料時應保留來源正字法欄位與標準化版本欄位。', '["卑南族", "族語語料/正字法"]', 'public', '["formosanbank_epark_readme"]', 60, '2026-06-11T14:20:00+08:00');
