INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_88b3fb95babe', 'fact', 'ancestral_house_ritual_space_public_sensitive', 'facts/ancestral_house_ritual_space_public_sensitive', '祖靈屋', '祖靈屋被公開描述為氏族祭祀與生命禮俗相關場所；平台只能介紹其文化意義，不公開內部儀式細節。', '["卑南族", "祖靈屋"]', 'preview', '["cip_puyuma_profile"]', 60, '2026-06-11T14:20:00+08:00');
