INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_4fad5c71acb3', 'fact', 'music_modern_public_figures_list_only', 'facts/music_modern_public_figures_list_only', '音樂/人物', '公開資料列名陸森寶、胡德夫、陳建年、紀曉君、張惠妹、陳明仁、桑布依等與卑南族音樂文化活力相關的人物；個別生平需另查來源。', '["卑南族", "音樂/人物"]', 'public', '["cip_puyuma_profile"]', 60, '2026-06-11T14:20:00+08:00');
INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_2e7a069378c0', 'fact', 'dance_personal_social_steps_public', 'facts/dance_personal_social_steps_public', '舞蹈', '公開資料指出卑南族舞蹈反映性別與年齡角色差異，跳舞時需遵守個人社會舞步。', '["卑南族", "舞蹈"]', 'preview', '["cip_puyuma_profile"]', 60, '2026-06-11T14:20:00+08:00');
INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_1e6724b7c8f6', 'fact', 'language_contact_south_north_public_detail', 'facts/language_contact_south_north_public_detail', '語言', '公開資料描述知本等南面部落受排灣族、魯凱族語影響較明顯，北面卑南部落則受阿美族語發音方式與漢語互動影響。', '["卑南族", "語言"]', 'public', '["cip_puyuma_profile"]', 60, '2026-06-11T14:20:00+08:00');
INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_41ce4f0f4f18', 'fact', 'clan_house_categories_public', 'facts/clan_house_categories_public', '親屬制度', '公開資料說明宗族中可區分大宗本家、小宗本家與分家等概念；平台不得推測或公開特定家族資料。', '["卑南族", "親屬制度"]', 'preview', '["cip_puyuma_profile"]', 60, '2026-06-11T14:20:00+08:00');
INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_a7e745272901', 'fact', 'traditional_marriage_current_change_public', 'facts/traditional_marriage_current_change_public', '婚姻制度', '公開資料指出傳統婚姻以從妻居與長女繼承為特徵之一，但現今傳統從妻居婚姻方式已較少見。', '["卑南族", "婚姻制度"]', 'preview', '["cip_puyuma_profile"]', 60, '2026-06-11T14:20:00+08:00');
INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_b3ee956a0a47', 'fact', 'rahan_calendar_weather_history_public', 'facts/rahan_calendar_weather_history_public', '祭司/社會制度', '公開資料描述祭司需熟知曆法、氣象、歷史、傳統歌謠與舞蹈，作為農耕與生活指引；平台可摘要，不可替代族內指導。', '["卑南族", "祭司/社會制度"]', 'preview', '["cip_puyuma_profile"]', 60, '2026-06-11T14:20:00+08:00');
INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_aa75f8fce4d4', 'fact', 'age_grade_training_skills_public', 'facts/age_grade_training_skills_public', '年齡階級/會所', '公開資料列出會所訓練可包含體能、知識、競走、摔角、野外求生與狩獵等技能；平台不得把它改寫成訓練手冊。', '["卑南族", "年齡階級/會所"]', 'preview', '["cip_puyuma_profile"]', 60, '2026-06-11T14:20:00+08:00');
INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_430a182e0d88', 'fact', 'belief_biruwa_scope_public', 'facts/belief_biruwa_scope_public', '信仰', '公開資料說明卑南族傳統信仰中的 biruwa 可涵蓋大自然、天地、四方、造人、祖先與死者之靈等範疇。', '["信仰", "卑南族"]', 'preview', '["cip_puyuma_profile"]', 60, '2026-06-11T14:20:00+08:00');
INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_0c9fe4762400', 'fact', 'belief_modern_religions_public', 'facts/belief_modern_religions_public', '信仰/現代生活', '公開資料指出卑南族現代生活中除傳統信仰外，也可見漢族信仰與西方基督宗教並存。', '["信仰/現代生活", "卑南族"]', 'preview', '["cip_puyuma_profile"]', 60, '2026-06-11T14:20:00+08:00');
INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_29b5a7bb8a98', 'fact', 'ritual_two_categories_public', 'facts/ritual_two_categories_public', '祭儀分類', '公開資料將卑南族傳統信仰祭典活動概分為農業相關歲時祭儀與個人生命歷程相關生命禮俗。', '["卑南族", "祭儀分類"]', 'preview', '["cip_puyuma_profile"]', 60, '2026-06-11T14:20:00+08:00');
INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_3b24828553f7', 'fact', 'ritual_calendar_months_public', 'facts/ritual_calendar_months_public', '祭儀時間軸', '公開資料將婦女除草完工慶列於3月、祖先登陸與發祥地祭祖列於4月、小米收穫祭列於7月、年祭列於12月；實際日期仍應以部落公告為準。', '["卑南族", "祭儀時間軸"]', 'preview', '["cip_puyuma_profile"]', 60, '2026-06-11T14:20:00+08:00');
