INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_e6de9dbfda40', 'vocabulary', 'puyuma-audio-e393a3d0412b', 'language/puyuma/audio/puyuma-audio-e393a3d0412b', '上課的時候，老師教我們數字的族語。', 'temakakesi mi lra, na sinsi pananadam kananta piningaiyan na aiyupan. / 上課的時候，老師教我們數字的族語。 / In class, the teacher taught us the Pinuyumayan language of numbers.', '["temakakesi mi lra, na sinsi pananadam kananta piningaiyan na aiyupan.", "上課的時候，老師教我們數字的族語。", "卑南語", "教室與學校", "知本卑南語", "語詞庫", "音檔"]', 'public', '["formosanbank_epark"]', 40, '2026-06-11T14:20:00+08:00');
INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_a47f60a94488', 'vocabulary', 'puyuma-audio-ebf64aa99678', 'language/puyuma/audio/puyuma-audio-ebf64aa99678', '我今天七點到學校。', 'harem kana wari pituwa tuki mu medek ku i kungkuwan. / 我今天七點到學校。 / I arrived at school at seven today.', '["harem kana wari pituwa tuki mu medek ku i kungkuwan.", "卑南語", "我今天七點到學校。", "教室與學校", "知本卑南語", "語詞庫", "音檔"]', 'public', '["formosanbank_epark"]', 40, '2026-06-11T14:20:00+08:00');
INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_7ffd48b7b18f', 'vocabulary', 'puyuma-audio-ecd06c07e0fd', 'language/puyuma/audio/puyuma-audio-ecd06c07e0fd', '上課了，老師走進教室，班長說:「起立!敬禮!」', 'puwateha mi lra temakesi zi, musavak na sinsi i takakesiyan, na niyam kemakezeng na sasevangan marengay, “katikeriz! sungal!” kema marengay. / 上課了，老師走進教室，班長說:「起立!敬禮!」 / It’s time for class, the teacher walked into the classroom, and the monitor said: “Stand up! Salute!”', '["puwateha mi lra temakesi zi, musavak na sinsi i takakesiyan, na niyam kemakezeng na sasevangan marengay, “katikeriz! sungal!” kema marengay.", "上課了，老師走進教室，班長說:「起立!敬禮!」", "卑南語", "教室與學校", "知本卑南語", "語詞庫", "音檔"]', 'public', '["formosanbank_epark"]', 40, '2026-06-11T14:20:00+08:00');
INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_aab6b04a9cf2', 'vocabulary', 'puyuma-audio-45dc39676f0e', 'language/puyuma/audio/puyuma-audio-45dc39676f0e', '我們大聲的說:「老師好。」', 'kematamuni mi marengay, “’inavayan sinsi.” / 我們大聲的說:「老師好。」 / We said loudly, “Hi, teacher.”', '["kematamuni mi marengay, “’inavayan sinsi.”", "卑南語", "問候語", "我們大聲的說:「老師好。」", "知本卑南語", "語詞庫", "音檔"]', 'public', '["formosanbank_epark"]', 40, '2026-06-11T14:20:00+08:00');
INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_f62206474514', 'vocabulary', 'puyuma-audio-d8bf21308421', 'language/puyuma/audio/puyuma-audio-d8bf21308421', '我們跟著老師唸，我們唱了數字歌。', 'miturus mi kana sinsi miyup, semenay mi kana senay na aiyupan. / 我們跟著老師唸，我們唱了數字歌。 / We followed the teacher to read, we sang the number song.', '["miturus mi kana sinsi miyup, semenay mi kana senay na aiyupan.", "卑南語", "我們跟著老師唸，我們唱了數字歌。", "教室與學校", "知本卑南語", "語詞庫", "音檔"]', 'public', '["formosanbank_epark"]', 40, '2026-06-11T14:20:00+08:00');
