INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_c88b1d70b294', 'vocabulary', 'puyuma-audio-7a6d8fcc6929', 'language/puyuma/audio/puyuma-audio-7a6d8fcc6929', '我有一個哥哥，他叫Uking，他今年11歲。', 'ulra i valri na ma’inay a sasa, tu ngadan maw i Uking, i intaw harem mu muketrep misama’ za saya tu ’ami. / 我有一個哥哥，他叫Uking，他今年11歲。 / I have a brother, his name is Uking, he is 11 years old.', '["ulra i valri na ma’inay a sasa, tu ngadan maw i Uking, i intaw harem mu muketrep misama’ za saya tu ’ami.", "卑南語", "我有一個哥哥，他叫Uking，他今年11歲。", "教室與學校", "知本卑南語", "語詞庫", "音檔"]', 'public', '["formosanbank_epark"]', 40, '2026-06-11T14:20:00+08:00');
