INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_3fe74bda8ad3', 'vocabulary', 'puyuma-audio-fba7d6ccb2ce', 'language/puyuma/audio/puyuma-audio-fba7d6ccb2ce', '我喜歡游泳，放假的時候，我們全家會一起去游泳。', 'sahar ku pakulimalima, nu katalaulepan i kungkuwan mu, salrangan mi saruma’enan mukuwa pakulimaya. / 我喜歡游泳，放假的時候，我們全家會一起去游泳。 / I like swimming. During the holidays, our whole family go swimming together.', '["sahar ku pakulimalima, nu katalaulepan i kungkuwan mu, salrangan mi saruma’enan mukuwa pakulimaya.", "卑南語", "我喜歡游泳，放假的時候，我們全家會一起去游泳。", "教室與學校", "知本卑南語", "語詞庫", "音檔"]', 'public', '["formosanbank_epark"]', 40, '2026-06-11T14:20:00+08:00');
INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_7f2d226fe539', 'vocabulary', 'puyuma-audio-15e0e7223043', 'language/puyuma/audio/puyuma-audio-15e0e7223043', '我喜歡認識新朋友，我們可以一起唱歌和游泳。', 'sahar ku manadam kana vekal na ali’an, aruwa mi salrangan semenay zi mukuwa pakulimaya. / 我喜歡認識新朋友，我們可以一起唱歌和游泳。 / I love meeting new people, we can sing and swim together.', '["sahar ku manadam kana vekal na ali’an, aruwa mi salrangan semenay zi mukuwa pakulimaya.", "卑南語", "我喜歡認識新朋友，我們可以一起唱歌和游泳。", "教室與學校", "知本卑南語", "語詞庫", "音檔"]', 'public', '["formosanbank_epark"]', 40, '2026-06-11T14:20:00+08:00');
