INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_44c8665904f5', 'vocabulary', 'puyuma-audio-3e8e95834aec', 'language/puyuma/audio/puyuma-audio-3e8e95834aec', '我今天七點到學校。', 'meredek ku i takesiyan a pituwa tuki harem kana wari. / 我今天七點到學校。 / I arrived at school at seven today.', '["meredek ku i takesiyan a pituwa tuki harem kana wari.", "卑南語", "我今天七點到學校。", "教室與學校", "西群卑南語", "語詞庫", "音檔"]', 'public', '["formosanbank_epark"]', 40, '2026-06-11T14:20:00+08:00');
INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_c51fc6feb628', 'vocabulary', 'puyuma-audio-595e0d902d82', 'language/puyuma/audio/puyuma-audio-595e0d902d82', '上課的時候，老師教我們數字的族語。', 'a temakesi mi mu, tu panadamaw mi kana sinsi za aiyupan. kananta piningaiyan. / 上課的時候，老師教我們數字的族語。 / In class, the teacher taught us the Pinuyumayan language of numbers.', '["a temakesi mi mu, tu panadamaw mi kana sinsi za aiyupan. kananta piningaiyan.", "上課的時候，老師教我們數字的族語。", "卑南語", "教室與學校", "西群卑南語", "語詞庫", "音檔"]', 'public', '["formosanbank_epark"]', 40, '2026-06-11T14:20:00+08:00');
INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_8c660a5d5d55', 'vocabulary', 'puyuma-audio-f720172af555', 'language/puyuma/audio/puyuma-audio-f720172af555', '我們家住在初鹿部落。', 'ulra naniyam ruma’ i Mulivelivek. / 我們家住在初鹿部落。 / Our family lives in Mulivelivek.', '["ulra naniyam ruma’ i Mulivelivek.", "卑南語", "我們家住在初鹿部落。", "教室與學校", "西群卑南語", "語詞庫", "音檔"]', 'public', '["formosanbank_epark"]', 40, '2026-06-11T14:20:00+08:00');
INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_29545df3821b', 'vocabulary', 'puyuma-audio-40cee4a7b4a2', 'language/puyuma/audio/puyuma-audio-40cee4a7b4a2', '上課了，老師走進教室，班長說:「起立!敬禮!」', 'kemiyarakaz lra temakesi, musavak na sinsi kana talrevaw, kema na pancang, “katikezir! sungal!” / 上課了，老師走進教室，班長說:「起立!敬禮!」 / It’s time for class, the teacher walked into the classroom, and the monitor said: “Stand up! Salute!”', '["kemiyarakaz lra temakesi, musavak na sinsi kana talrevaw, kema na pancang, “katikezir! sungal!”", "上課了，老師走進教室，班長說:「起立!敬禮!」", "卑南語", "教室與學校", "西群卑南語", "語詞庫", "音檔"]', 'public', '["formosanbank_epark"]', 40, '2026-06-11T14:20:00+08:00');
INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_0c4f05916f77', 'vocabulary', 'puyuma-audio-f3b81e5909b4', 'language/puyuma/audio/puyuma-audio-f3b81e5909b4', '我們大聲的說:「老師好。」', 'kema’izang mi marengay, “’inavayan sinsi.” / 我們大聲的說:「老師好。」 / We said loudly, “Hi, teacher.”', '["kema’izang mi marengay, “’inavayan sinsi.”", "卑南語", "問候語", "我們大聲的說:「老師好。」", "西群卑南語", "語詞庫", "音檔"]', 'public', '["formosanbank_epark"]', 40, '2026-06-11T14:20:00+08:00');
INSERT INTO public_search_documents_v16 (id, entity_type, entity_id, slug, title_zh, body_zh, keywords_json, release_channel, source_ids_json, weight, updated_at) VALUES ('search_42488d292565', 'vocabulary', 'puyuma-audio-c1f05d8abee4', 'language/puyuma/audio/puyuma-audio-c1f05d8abee4', '我們跟著老師唸，我們唱了數字歌。', 'iturus mi kana sinsi miyup, zi semenay mi kana senay na aiyupan. / 我們跟著老師唸，我們唱了數字歌。 / We followed the teacher to read, we sang the number song.', '["iturus mi kana sinsi miyup, zi semenay mi kana senay na aiyupan.", "卑南語", "我們跟著老師唸，我們唱了數字歌。", "教室與學校", "西群卑南語", "語詞庫", "音檔"]', 'public', '["formosanbank_epark"]', 40, '2026-06-11T14:20:00+08:00');
